window.VOCAB_TERMS = window.VOCAB_TERMS || {};
window.VOCAB_TERMS["ai"] = {"ai--ai-agent":{"definition":"챗봇은 물어보면 답하고 끝난다. 에이전트는 목표를 여러 단계로 쪼개고, 필요한 도구를 골라 쓰고, 그 결과를 보고 다음 행동을 정하는 일을 목표에 닿을 때까지 반복한다.","analogy":"심부름을 맡긴 사람. 백과사전은 물어본 것만 답하지만, 심부름꾼은 가게에 다녀오고 문이 닫혀 있으면 다른 가게를 찾는다.","example":"로봇청소기는 청소 단추 하나만 눌러도 방을 스스로 돌고, 문턱에 걸리면 방향을 바꿔 다시 간다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"가장 널리 쓰이는 방식이 ReAct다. 생각(Thought)으로 무엇이 필요한지 정하고, 행동(Action)으로 도구를 부르고, 관찰(Observation)로 결과를 확인한다. 목표에 닿았으면 끝내고, 아니면 관찰 결과를 들고 다시 생각으로 돌아간다.\n\n기억은 두 종류로 나뉜다. 지금 하고 있는 작업의 진행 상황이 단기 기억이고, 과거에 무엇이 통했고 무엇이 실패했는지가 장기 기억이다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **여러 도구를 거치는 조사** — 검색으로 자료를 모으고 계산기로 수치를 맞춘 다음, 정리해서 한 번에 내놓는다.\n- **파일을 다루는 작업** — 폴더를 훑고 조건에 맞는 파일만 골라낸 뒤 내용을 읽어 요약한다.\n- **실패를 딛고 가는 작업** — 파일 이름이 틀려 읽기에 실패하면 목록을 먼저 확인하고 이름을 고쳐 다시 읽는다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **에이전트는 더 똑똑한 모델이다** — 모델은 같은 것을 쓴다. 달라지는 건 도구를 쥐여주고 결과를 다시 보게 만든 바깥 구조다.\n- **목표만 주면 알아서 다 한다** — 쓸 수 있는 도구를 미리 정해줘야 한다. 도구함에 없는 일은 아무리 반복해도 못 한다.\n- **실패해도 재시도하니 결국 성공한다** — 판단 자체가 어긋나 있으면 같은 실수를 되풀이할 뿐이다. 그래서 몇 번까지 돌지 정해둔다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **반복 횟수를 정해둔다.** 목표에 닿지 못하면 끝없이 돈다. 몇 바퀴까지 돌지 정하고 그 뒤에는 멈추게 한다.\n- **도구가 할 수 있는 일의 범위를 정해둔다.** 파일을 지우거나 돈을 쓰는 도구를 쥐여주면 판단이 어긋났을 때 되돌리기 어렵다."}],"figure":"```도해\n흐름: 에이전트는 무슨 순서로 일을 하나\n사용자 :: 목표를 말한다. \"내일 날씨 알려줘\"\nLLM :: 무엇이 필요한지 판단한다. 날씨 도구다\n에이전트 :: 도구를 부른다. 도시와 날짜를 넘긴다\n도구 :: 실행하고 결과를 돌려준다\nLLM :: 결과를 보고 더 할 일이 있는지 정한다\n@ 다시 판단으로 :: 없으면 답하고 끝, 있으면 한 바퀴 더\n= 생각하고 행동하고 결과를 보는 한 바퀴를, 목표에 닿을 때까지 돈다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 여러 단계가 필요한 일을 시키면 어떻게 되나\n일반 LLM || AI Agent\n할 수 있는 일 :: 답만 돌려준다 || 도구를 직접 쓴다\n단계 :: 한 번 답하고 끝 || 목표까지 반복\n오류가 나면 :: 거기서 멈춘다 || 고쳐서 다시 한다\n= 답을 아는 것과 일을 끝내는 것은 다르다\n```\n\n\"내일 날씨를 보고 비가 오면 우산 가격을 비교해줘\"를 일반 LLM에게 시키면 답은 하나다. 날씨를 조회할 수 없고 웹을 볼 수 없다는 것. 사용자가 직접 날씨를 확인하고, 쇼핑몰을 열고, 가격을 옮겨 적어야 한다.\n\n에이전트는 그 사이를 메운다. 날씨 도구를 부르고, 결과가 \"비\"면 검색 도구로 넘어가고, 모은 가격을 정리해서 내놓는다. 중간에 도구가 실패해도 무엇이 잘못됐는지 보고 다시 시도한다."},"compose":{"label":"무엇으로 되어 있나","head":"🧱 구성","body":"```도해\n층: 어디까지가 모델이고 어디부터 붙인 것인가\nLLM :: 모델 자체. 다음 행동을 고르기만 한다\n계획·기억 :: 목표를 단계로 쪼개고 지금까지를 들고 있다\n도구 :: 웹 검색, 파일 읽기, 코드 실행. 밖에 닿는 손\n= 에이전트로 만든 건 모델이 아니라 그 위에 얹은 두 겹이다\n```"},"recap":"AI Agent는 목표를 받아 생각하고 도구를 쓰고 결과를 보는 일을 반복하는 AI다. 모델이 달라져서가 아니라 도구와 반복이 바깥에 붙어 있어서 일을 끝까지 밀고 간다. 쓸 도구와 멈출 지점을 정하는 것은 사람의 몫으로 남는다.","check":[{"q":"같은 LLM을 쓰는데 에이전트만 여러 단계짜리 일을 끝낼 수 있는 이유는","at":"흔한 오해"},{"q":"도구를 실행했더니 오류가 났다. 에이전트는 그다음에 무엇을 하나","at":"실제 사례"},{"q":"반복 횟수에 한계를 두지 않으면 무슨 일이 생기나","at":"주의사항"}],"myths":[{"wrong":"에이전트는 더 똑똑한 모델이다","right":"모델은 같은 것을 쓴다. 달라지는 건 도구를 쥐여주고 결과를 다시 보게 만든 바깥 구조다."},{"wrong":"목표만 주면 알아서 다 한다","right":"쓸 수 있는 도구를 미리 정해줘야 한다. 도구함에 없는 일은 아무리 반복해도 못 한다."},{"wrong":"실패해도 재시도하니 결국 성공한다","right":"판단 자체가 어긋나 있으면 같은 실수를 되풀이할 뿐이다. 그래서 몇 번까지 돌지 정해둔다."}],"cases":[{"label":"여러 도구를 거치는 조사","note":"검색으로 자료를 모으고 계산기로 수치를 맞춘 다음, 정리해서 한 번에 내놓는다."},{"label":"파일을 다루는 작업","note":"폴더를 훑고 조건에 맞는 파일만 골라낸 뒤 내용을 읽어 요약한다."},{"label":"실패를 딛고 가는 작업","note":"파일 이름이 틀려 읽기에 실패하면 목록을 먼저 확인하고 이름을 고쳐 다시 읽는다."}],"dia":{"shape":"흐름","title":"에이전트는 무슨 순서로 일을 하나","rows":[{"who":"사용자","what":"목표를 말한다. \"내일 날씨 알려줘\""},{"who":"LLM","what":"무엇이 필요한지 판단한다. 날씨 도구다"},{"who":"에이전트","what":"도구를 부른다. 도시와 날짜를 넘긴다"},{"who":"도구","what":"실행하고 결과를 돌려준다"},{"who":"LLM","what":"결과를 보고 더 할 일이 있는지 정한다"}],"sum":"생각하고 행동하고 결과를 보는 한 바퀴를, 목표에 닿을 때까지 돈다","loop":{"who":"다시 판단으로","what":"없으면 답하고 끝, 있으면 한 바퀴 더"}}},"ai--agent":{"definition":"LLM은 물으면 답만 한다. 여기에 검색이나 실행 같은 도구를 쥐여주고, 한 번에 끝내지 않고 결과를 보며 다음 행동을 다시 정하게 만든 것이 Agent다.","analogy":"심부름. 재료를 사 오라고만 말하면 알아서 가게를 고르고, 물건이 없으면 다른 가게로 간다. 한 걸음마다 지시하는 것과 다르다.","example":"스마트폰에 대고 내일 일곱 시에 깨워 달라고 말하면 알람 앱이 열려 시각까지 맞춰져 있다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"Agent 를 이루는 것은 넷이다.\n\n- **LLM** — 다음에 무엇을 할지 정하는 자리\n- **도구** — 검색, 계산, 파일 읽기. 밖에 닿는 손\n- **기억** — 지금까지 무엇을 했는지 들고 있다\n- **멈춤 조건** — 횟수나 비용의 한도. 없으면 안 끝난다\n\n도구가 없으면 말만 하고, 기억이 없으면 같은 일을 반복한다.\n\n행동을 정하는 방식에는 몇 가지 틀이 있다. 생각하고 도구를 쓰고 결과를 본 뒤 다시 생각하는 것을 반복하는 ReAct, 전체 계획을 먼저 세워두고 단계별로 실행하는 Plan-and-Execute가 대표적이다.\n\n멈춤 조건은 설계에 포함해야 한다. 최대 반복 횟수를 정해두지 않으면 답을 못 찾는 상황에서 같은 자리를 맴돈다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **메일 정리** — 메일을 읽어오는 도구를 붙여주면 목록을 훑고 중요한 것만 골라 요약해 돌려준다.\n- **자료 조사** — 검색, 정리, 문서 작성을 지시 한 번으로 이어서 한다.\n- **코드 수정** — 코드를 쓰고 실행해본 뒤 오류가 나면 고쳐서 다시 실행하는 것을 반복한다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **Agent는 LLM보다 똑똑한 모델이다** — 모델은 같은 것을 쓴다. 도구를 쥐여주고 여러 번 돌리는 껍데기가 붙었을 뿐이다.\n- **한 번 시키면 알아서 끝까지 간다** — 멈출 조건을 정해두지 않으면 끝을 못 찾고 횟수만 채운 뒤 중간 상태로 돌아온다.\n- **Agent를 쓰면 답이 더 정확해진다** — 틀리게 답하던 모델은 여전히 틀린다. 달라지는 건 정확도가 아니라 할 수 있는 일의 범위다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **호출 횟수가 곧 비용이다.** 한 번의 대화가 열 번 넘는 모델 호출로 늘어난다. 반복 한도를 정해두지 않으면 비용이 예측되지 않는다.\n- **위험한 도구는 처음부터 빼둔다.** 삭제나 결제처럼 되돌릴 수 없는 도구는 목록에서 제외하거나 사람 확인을 거치게 한다."}],"figure":"```도해\n흐름: 목표 한 줄을 주면 Agent 는 무엇을 하나\n사용자 :: \"경쟁사 분석 보고서 써줘\" 한 줄만 준다\nAgent :: 무엇부터 할지 정한다. 검색이 먼저다\n도구 :: 검색을 실행하고 결과를 돌려준다\nAgent :: 결과를 보고 다음 할 일을 다시 정한다\nAgent :: 충분하다고 판단하면 멈춘다\n< 사용자 :: 완성된 보고서를 받는다\n= 지시가 아니라 목표를 주고, 중간 판단을 넘기는 것이 차이다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: LLM 에게만 물으면 어디서 막히나\nAgent 없이 || Agent 로\n바깥 정보 :: 모른다고 답함 || 검색해서 가져옴\n여러 단계 :: 사람이 이어붙임 || 스스로 이어감\n중간 실패 :: 거기서 멈춤 || 다른 길을 시도\n= 답을 만드는 것과 일을 끝내는 것은 다르다\n```\n\n\"이메일 확인하고 중요한 것만 요약해줘\"라고 하면 LLM은 이메일에 닿을 수가 없어서 못 한다고 답한다. 자료를 모으고 정리하고 문서로 쓰는 일도 마찬가지다. 각 단계는 할 수 있지만 그걸 이어붙이는 건 사람 몫으로 남는다.\n\nAgent는 그 이어붙이는 자리를 가져간다. 도구를 호출해 결과를 받고, 그 결과를 보고 다음에 무엇을 할지 다시 정한다. 도중에 오류가 나도 사람을 부르지 않고 다른 방법을 먼저 시도한다."},"recap":"Agent는 LLM에 도구와 반복 판단을 붙여 목표를 끝까지 밀고 가게 만든 구조다. 모델이 똑똑해진 것이 아니라 손발이 생긴 것이고, 그만큼 반복 한도와 권한을 정해두는 일이 따라온다.","check":[{"q":"같은 모델을 쓰는데 Agent로 감쌌을 때만 할 수 있게 되는 일은 어떤 것인가","at":"실제 사례"},{"q":"반복 한도를 정해두지 않으면 무슨 일이 벌어지나","at":"주의사항"},{"q":"메일을 요약해달라는 요청에서 LLM 혼자로는 어디서 막히나","at":"해결하는 문제"}],"myths":[{"wrong":"Agent는 LLM보다 똑똑한 모델이다","right":"모델은 같은 것을 쓴다. 도구를 쥐여주고 여러 번 돌리는 껍데기가 붙었을 뿐이다."},{"wrong":"한 번 시키면 알아서 끝까지 간다","right":"멈출 조건을 정해두지 않으면 끝을 못 찾고 횟수만 채운 뒤 중간 상태로 돌아온다."},{"wrong":"Agent를 쓰면 답이 더 정확해진다","right":"틀리게 답하던 모델은 여전히 틀린다. 달라지는 건 정확도가 아니라 할 수 있는 일의 범위다."}],"cases":[{"label":"메일 정리","note":"메일을 읽어오는 도구를 붙여주면 목록을 훑고 중요한 것만 골라 요약해 돌려준다."},{"label":"자료 조사","note":"검색, 정리, 문서 작성을 지시 한 번으로 이어서 한다."},{"label":"코드 수정","note":"코드를 쓰고 실행해본 뒤 오류가 나면 고쳐서 다시 실행하는 것을 반복한다."}],"dia":{"shape":"흐름","title":"목표 한 줄을 주면 Agent 는 무엇을 하나","rows":[{"who":"사용자","what":"\"경쟁사 분석 보고서 써줘\" 한 줄만 준다"},{"who":"Agent","what":"무엇부터 할지 정한다. 검색이 먼저다"},{"who":"도구","what":"검색을 실행하고 결과를 돌려준다"},{"who":"Agent","what":"결과를 보고 다음 할 일을 다시 정한다"},{"who":"Agent","what":"충분하다고 판단하면 멈춘다"},{"who":"사용자","what":"완성된 보고서를 받는다","back":true}],"sum":"지시가 아니라 목표를 주고, 중간 판단을 넘기는 것이 차이다"}},"ai--cnn":{"definition":"보통의 신경망은 픽셀을 하나씩 따로 받는다. 100×100 이미지면 입력이 1만 개고, 옆 픽셀과 붙어 있다는 사실은 사라진다. CNN은 작은 창을 이미지 위로 옮겨가며 보기 때문에 그 관계가 남는다.","analogy":"도장. 같은 무늬가 새겨진 도장을 사진 위 여기저기에 찍어보며 어디에서 잘 맞는지 표시하는 것과 비슷하다.","example":"휴대폰 사진첩이 사람 얼굴별로 앨범을 만들어 두는 것이 이 일을 하고 있는 자리다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"필터는 작은 숫자 격자다. 가운데를 크게 하고 둘레를 음수로 두면 밝기가 갑자기 꺾이는 자리, 곧 모서리에 큰 값이 나온다.\n\n```\n-1 -1 -1\n-1  8 -1\n-1 -1 -1\n```\n\n이 격자를 이미지 위에서 한 칸씩 옮기며 곱하고 더한 결과가 다음 층의 입력이 된다. 어떤 숫자를 넣을지는 사람이 정하지 않고 학습으로 정해진다.\n\n층 사이에는 풀링이 들어간다. 2×2 영역에서 가장 큰 값만 남기는 식으로 크기를 절반으로 줄이는데, 이 덕분에 무늬가 몇 픽셀 밀려 있어도 같은 결과가 나온다."},{"slot":"compare","label":"무엇과 비교되나","head":"📊 비교: 대표적인 CNN 구조","body":"| 모델 | 연도 | 달라진 점 |\n|---|---|---|\n| LeNet-5 | 1998 | 최초의 CNN. 손글씨 인식 |\n| AlexNet | 2012 | ImageNet 우승. ReLU 사용 |\n| VGGNet | 2014 | 층을 16~19개까지 깊게 |\n| ResNet | 2015 | 층을 건너뛰는 연결로 152층까지 |"},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **얼굴 인식** — 사진에서 얼굴 위치를 찾고 누구인지 고르는 데 쓴다.\n- **물체 감지** — 한 장면에서 자동차 3대와 사람 5명을 각각 상자로 표시한다.\n- **학습된 모델 재사용** — 이미 학습된 모델을 가져와 마지막 층만 바꿔 쓰는 방식이 흔하다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **CNN은 이미지에만 쓴다** — 이웃끼리 뭉쳐 뜻을 이루는 데이터면 쓸 수 있다. 소리 파형이나 문장에도 같은 방식을 적용한다.\n- **필터의 숫자를 사람이 정해준다** — 어떤 무늬를 찾을지까지 학습으로 정해진다. 사람이 정하는 건 필터의 크기와 개수다.\n- **층을 깊게 쌓을수록 좋아진다** — 어느 지점을 넘으면 오히려 학습이 안 된다. 층을 건너뛰는 연결 같은 장치가 나온 이유가 그것이다."}],"figure":"```도해\n흐름: 사진 한 장이 \"고양이\" 라는 답이 되기까지 무엇을 지나나\n입력 :: 픽셀 값이 격자 그대로 들어온다\n합성곱 :: 작은 필터를 옮겨가며 무늬를 찾는다\n풀링 :: 크기를 줄인다. 위치가 조금 달라도 견딘다\n반복 :: 합성곱과 풀링을 다시. 무늬가 커진다\n완전연결 :: 모아둔 특징을 근거로 분류한다\n출력 :: 고양이 90%, 개 10%\n= 앞에서 무늬를 찾고, 뒤에서 그 무늬를 근거로 고른다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 픽셀을 하나씩 따로 보면 무엇이 안 되나\n일반 신경망 || CNN\n이웃 픽셀 :: 관계가 끊김 || 함께 본다\n가중치 :: 픽셀마다 따로 || 필터를 공유\n위치 이동 :: 다른 것으로 봄 || 같은 것으로 봄\n= 이미지는 이웃끼리 뭉쳐 뜻을 이루므로 이웃을 같이 봐야 한다\n```\n\n눈이 사진의 어디에 있든 눈은 눈이다. 픽셀을 하나씩 독립적으로 받는 신경망은 이걸 모른다. 고양이가 왼쪽에 있는 사진과 오른쪽에 있는 사진이 완전히 다른 입력으로 들어온다.\n\nCNN은 같은 필터를 이미지 전체에 옮겨가며 쓴다. 그래서 무늬가 어디에 있든 같은 무늬로 잡히고, 학습해야 할 값의 개수도 크게 줄어든다."},"compose":{"label":"무엇으로 되어 있나","head":"🧱 구성","body":"```도해\n층: 층이 깊어질수록 무엇을 알아보나\n1층 :: 밝기가 꺾이는 자리. 선과 모서리\n2층 :: 선이 모인 모양. 곡선, 꺾임\n3층 :: 눈이나 코 같은 부분\n4층 :: 부분들의 배치. 고양이인지 아닌지\n= 앞층이 찾은 것을 재료로 뒷층이 더 큰 것을 찾는다\n```"},"recap":"CNN은 작은 필터를 이미지 위로 옮겨가며 무늬를 찾는 신경망이다. 앞층은 선과 모서리를 보고 뒷층은 그것이 모인 부분을 보며, 마지막에 그 특징들로 분류한다.","check":[{"q":"픽셀을 하나씩 따로 받는 신경망이 이미지에서 약한 이유는","at":"해결하는 문제"},{"q":"층이 깊어지면 각 층이 알아보는 것은 어떻게 달라지나","at":"구성"},{"q":"필터에 넣을 숫자는 누가 정하고, 사람이 정하는 것은 무엇인가","at":"흔한 오해"}],"myths":[{"wrong":"CNN은 이미지에만 쓴다","right":"이웃끼리 뭉쳐 뜻을 이루는 데이터면 쓸 수 있다. 소리 파형이나 문장에도 같은 방식을 적용한다."},{"wrong":"필터의 숫자를 사람이 정해준다","right":"어떤 무늬를 찾을지까지 학습으로 정해진다. 사람이 정하는 건 필터의 크기와 개수다."},{"wrong":"층을 깊게 쌓을수록 좋아진다","right":"어느 지점을 넘으면 오히려 학습이 안 된다. 층을 건너뛰는 연결 같은 장치가 나온 이유가 그것이다."}],"cases":[{"label":"얼굴 인식","note":"사진에서 얼굴 위치를 찾고 누구인지 고르는 데 쓴다."},{"label":"물체 감지","note":"한 장면에서 자동차 3대와 사람 5명을 각각 상자로 표시한다."},{"label":"학습된 모델 재사용","note":"이미 학습된 모델을 가져와 마지막 층만 바꿔 쓰는 방식이 흔하다."}],"dia":{"shape":"흐름","title":"사진 한 장이 \"고양이\" 라는 답이 되기까지 무엇을 지나나","rows":[{"who":"입력","what":"픽셀 값이 격자 그대로 들어온다"},{"who":"합성곱","what":"작은 필터를 옮겨가며 무늬를 찾는다"},{"who":"풀링","what":"크기를 줄인다. 위치가 조금 달라도 견딘다"},{"who":"반복","what":"합성곱과 풀링을 다시. 무늬가 커진다"},{"who":"완전연결","what":"모아둔 특징을 근거로 분류한다"},{"who":"출력","what":"고양이 90%, 개 10%"}],"sum":"앞에서 무늬를 찾고, 뒤에서 그 무늬를 근거로 고른다"}},"ai--chunking":{"definition":"RAG에서 문서를 넣기 전에 거치는 단계다. 자르는 기준을 무엇으로 잡느냐에 따라 나중에 검색되는 조각이 달라진다.","analogy":"책. 통째로 들고 다니지 않고 장과 절로 나눠두면 필요한 쪽만 펴서 본다.","example":"한 시간짜리 유튜브 영상 아래 붙은 챕터 목록에서 필요한 대목만 눌러 본 그 자리다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"자르는 방법은 크게 셋이다. 글자 수로 끊는 고정 크기, 문단이나 문장 경계에서 끊는 의미 단위, 문서에 이미 있는 구조를 쓰는 방식이다. 법령이나 사규처럼 조항 번호가 붙은 문서는 세 번째가 가장 잘 맞는다.\n\n```python\ndef fixed_size(text, size=500, overlap=50):\n    chunks, start = [], 0\n    while start < len(text):\n        chunks.append(text[start:start + size])\n        start += size - overlap\n    return chunks\n```\n\n`overlap` 이 겹치는 구간이다. 겹침 없이 자르면 경계에 걸친 문장이 양쪽 어디에서도 온전하지 않다. 앞 조각의 끝 몇십 자를 다음 조각의 앞에 다시 넣어 그 손실을 줄인다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **사규 검색** — 조항 번호를 기준으로 잘라두고 조각마다 조항 번호를 함께 저장해 답변에 출처를 붙인다.\n- **긴 보고서** — 소제목 단위로 자르면 한 조각 안의 내용이 한 주제로 모여 검색 정확도가 올라간다.\n- **답이 자꾸 어긋날 때** — 모델을 바꾸기 전에 자르는 단위부터 바꿔보고 결과를 견준다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **청크는 작을수록 정확하다** — 너무 작으면 문장 앞뒤가 끊겨 그 조각만 봐서는 무슨 말인지 알 수 없다. 검색에는 걸려도 답이 안 나온다.\n- **겹치기는 저장 공간 낭비다** — 겹침이 없으면 경계에 걸친 문장이 어느 쪽에서도 온전하지 않다. 50자에서 200자 정도의 겹침은 그 손실을 막는 값이다.\n- **한 번 잘라두면 끝난다** — 자르는 기준이 검색 품질을 정한다. 답이 어긋나기 시작하면 자른 단위를 먼저 의심한다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **크기는 500자에서 1500자 사이가 무난하다.** 이보다 작으면 문맥이 끊기고 크면 필요 없는 내용까지 딸려 온다.\n- **한국어는 어절 경계를 조심한다.** 공백만 보고 끊으면 조사가 잘려 나가 검색이 안 걸릴 수 있다."}],"figure":"```도해\n흐름: 100쪽짜리 문서로 질문 하나에 어떻게 답하나\n원본 문서 :: 조항이나 문단 단위로 자른다\n청크 :: 조각마다 벡터(뜻의 좌표)로 바꿔 저장한다\n질문 :: 들어온 질문도 같은 방식으로 바꾼다\n검색 :: 가까운 조각 몇 개만 고른다\nLLM :: 고른 조각만 읽고 답을 만든다\n= 문서 전체가 아니라 필요한 조각만 모델 앞에 놓는다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 문서를 통째로 넣으면 무엇이 걸리나\n통째로 || 잘라서\n입력 길이 :: 한도를 넘는다 || 조각만 넣는다\n비용 :: 매번 전부 낸다 || 필요한 만큼만\n검색 결과 :: 엉뚱한 대목까지 || 해당 조항만\n= 자르는 이유는 넣기 위해서만이 아니라 찾기 위해서이기도 하다\n```\n\n100쪽짜리 취업규칙을 통째로 모델에 넣으면 입력 한도를 넘고, 넘지 않더라도 매 질문마다 100쪽 값을 낸다.\n\n더 걸리는 것은 검색 쪽이다. 문서 하나가 통으로 한 덩어리면 \"육아휴직 기간은?\" 이라고 물었을 때 그 문서 전체가 걸린다. 조항 단위로 잘라두면 해당 조항만 걸려 나온다."},"recap":"Chunking은 긴 문서를 검색할 수 있는 크기로 잘라두는 일이다. 모델 입력 한도 때문에 자르기도 하지만, 더 큰 이유는 필요한 대목만 골라내기 위해서다. 자르는 기준과 겹침의 양이 검색 품질을 정한다.","check":[{"q":"조각을 100자로 잘게 자르면 검색은 걸리는데 답이 안 나오는 이유는","at":"흔한 오해"},{"q":"겹침을 0으로 두면 어떤 문장이 손해를 보나","at":"작동 원리"},{"q":"조항 번호가 붙은 사규는 무엇을 기준으로 자르고 무엇을 함께 저장하나","at":"실제 사례"}],"myths":[{"wrong":"청크는 작을수록 정확하다","right":"너무 작으면 문장 앞뒤가 끊겨 그 조각만 봐서는 무슨 말인지 알 수 없다. 검색에는 걸려도 답이 안 나온다."},{"wrong":"겹치기는 저장 공간 낭비다","right":"겹침이 없으면 경계에 걸친 문장이 어느 쪽에서도 온전하지 않다. 50자에서 200자 정도의 겹침은 그 손실을 막는 값이다."},{"wrong":"한 번 잘라두면 끝난다","right":"자르는 기준이 검색 품질을 정한다. 답이 어긋나기 시작하면 자른 단위를 먼저 의심한다."}],"cases":[{"label":"사규 검색","note":"조항 번호를 기준으로 잘라두고 조각마다 조항 번호를 함께 저장해 답변에 출처를 붙인다."},{"label":"긴 보고서","note":"소제목 단위로 자르면 한 조각 안의 내용이 한 주제로 모여 검색 정확도가 올라간다."},{"label":"답이 자꾸 어긋날 때","note":"모델을 바꾸기 전에 자르는 단위부터 바꿔보고 결과를 견준다."}],"dia":{"shape":"흐름","title":"100쪽짜리 문서로 질문 하나에 어떻게 답하나","rows":[{"who":"원본 문서","what":"조항이나 문단 단위로 자른다"},{"who":"청크","what":"조각마다 벡터(뜻의 좌표)로 바꿔 저장한다"},{"who":"질문","what":"들어온 질문도 같은 방식으로 바꾼다"},{"who":"검색","what":"가까운 조각 몇 개만 고른다"},{"who":"LLM","what":"고른 조각만 읽고 답을 만든다"}],"sum":"문서 전체가 아니라 필요한 조각만 모델 앞에 놓는다"}},"ai--context-window":{"definition":"길이는 글자가 아니라 토큰으로 센다. 질문과 지난 대화와 붙여 보낸 문서가 전부 이 한도를 나눠 쓰고, 모델이 내놓을 답도 같은 한도 안에 들어가야 한다.","analogy":"책상. 아무리 넓어도 올려둔 것만 보면서 일한다. 책장에 꽂힌 책은 올려놓기 전까지 없는 것과 같다.","example":"긴 문서를 통째로 붙여넣었더니 길이가 넘친다며 거절당하는 그 순간이 창의 끝이다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"토큰은 글을 자른 조각이다. 영어는 단어 하나가 대체로 한두 토큰이고 한국어는 같은 글자 수라도 토큰이 더 많이 나온다. 그래서 창 크기를 글자 수로 환산해 외우면 잘 맞지 않는다.\n\n입력과 출력이 같은 창을 나눠 쓴다는 점도 놓치기 쉽다. 창을 입력으로 거의 채우면 답이 들어설 자리가 남지 않아 중간에서 끊긴다."},{"slot":"compare","label":"무엇과 비교되나","head":"📊 비교: 창 크기의 규모","body":"| 모델 | 창 크기 | 대략 분량 |\n|---|---|---|\n| GPT-3.5 | 4K 토큰 | 짧은 글 몇 페이지 |\n| GPT-4 Turbo | 128K 토큰 | 책 한 권 |\n| Claude 3.5 Sonnet | 200K 토큰 | 책 한 권 반 |\n| Gemini 1.5 Pro | 1M 토큰 | 책 여러 권 |"},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **긴 보고서 요약** — 창보다 긴 문서는 조각으로 나눠 각각 요약하고 그 요약을 다시 합친다.\n- **오래 이어지는 상담** — 앞부분 대화를 요약본으로 바꿔 넣어 창 안에 남긴다.\n- **문서 검색을 붙이는 이유** — 전체를 넣는 대신 질문과 관련된 조각만 찾아 넣는다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **모델이 앞에서 한 말을 기억하고 있다** — 기억하지 않는다. 프로그램이 매번 지난 대화를 통째로 다시 붙여 보내는 것이고, 그래서 대화가 길수록 같은 질문에도 비용이 오른다.\n- **창이 크면 채울수록 좋다** — 넣은 만큼 돈과 시간이 든다. 관련 없는 글까지 채우면 느려지고 답도 흐려진다.\n- **창은 입력 길이를 뜻한다** — 답변도 같은 창을 나눠 쓴다. 입력으로 창을 거의 채우면 답이 짧아지거나 잘린다."}],"figure":"```도해\n흐름: 대화가 길어지면 앞부분은 어디로 가나\n사용자 :: 새 질문 한 줄을 보낸다\n프로그램 :: 지난 대화 전체를 앞에 붙여 보낸다\n모델 :: 붙어 온 글을 토큰으로 센다\n모델 :: 창을 넘으면 거절하거나 앞부분이 잘린다\n< 사용자 :: 창 안에 남은 것만 보고 만든 답을 받는다\n@ 다음 질문 :: 지난 대화가 또 통째로 붙어 온다\n= 모델이 기억하는 게 아니라 매번 통째로 다시 읽는 것이다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 창 크기를 모르고 쓰면 어떤 일이 생기나\n모르고 쓰면 || 알고 쓰면\n긴 문서 :: 통째로 넣는다 || 나눠서 넣는다\n결과 :: 길이 초과로 실패 || 필요한 데만 답\n비용 :: 안 쓸 글까지 낸다 || 넣은 만큼만\n= 창은 늘릴 수 없으니 무엇을 넣을지 고르는 문제가 된다\n```\n\n모델에게 자료를 주는 방법은 창 안에 넣는 것 하나뿐이다. 사내 문서 전체를 읽히고 싶어도 창보다 길면 들어가지 않고, 대화를 길게 이어가면 앞부분부터 밀려 나간다.\n\n그래서 창 크기를 아는 일은 곧 무엇을 넣고 무엇을 뺄지 정하는 일이 된다. 질문과 관련된 조각만 찾아 넣거나, 지난 대화를 요약해 압축하거나, 문서를 나눠 여러 번 묻는 방식이 여기서 나온다."},"recap":"Context Window 는 모델이 한 번에 볼 수 있는 토큰 수이고, 입력과 출력이 그 한도를 함께 쓴다. 늘릴 수 없는 값이라 무엇을 넣을지 고르는 일이 실제 작업이 된다.","check":[{"q":"대화가 길어질수록 같은 질문에 비용이 더 드는 이유는","at":"흔한 오해"},{"q":"창보다 긴 문서를 요약해야 할 때 무엇을 하나","at":"실제 사례"},{"q":"입력을 창 끝까지 채웠더니 답이 중간에 끊긴다면 왜인가","at":"작동 원리"}],"myths":[{"wrong":"모델이 앞에서 한 말을 기억하고 있다","right":"기억하지 않는다. 프로그램이 매번 지난 대화를 통째로 다시 붙여 보내는 것이고, 그래서 대화가 길수록 같은 질문에도 비용이 오른다."},{"wrong":"창이 크면 채울수록 좋다","right":"넣은 만큼 돈과 시간이 든다. 관련 없는 글까지 채우면 느려지고 답도 흐려진다."},{"wrong":"창은 입력 길이를 뜻한다","right":"답변도 같은 창을 나눠 쓴다. 입력으로 창을 거의 채우면 답이 짧아지거나 잘린다."}],"cases":[{"label":"긴 보고서 요약","note":"창보다 긴 문서는 조각으로 나눠 각각 요약하고 그 요약을 다시 합친다."},{"label":"오래 이어지는 상담","note":"앞부분 대화를 요약본으로 바꿔 넣어 창 안에 남긴다."},{"label":"문서 검색을 붙이는 이유","note":"전체를 넣는 대신 질문과 관련된 조각만 찾아 넣는다."}],"dia":{"shape":"흐름","title":"대화가 길어지면 앞부분은 어디로 가나","rows":[{"who":"사용자","what":"새 질문 한 줄을 보낸다"},{"who":"프로그램","what":"지난 대화 전체를 앞에 붙여 보낸다"},{"who":"모델","what":"붙어 온 글을 토큰으로 센다"},{"who":"모델","what":"창을 넘으면 거절하거나 앞부분이 잘린다"},{"who":"사용자","what":"창 안에 남은 것만 보고 만든 답을 받는다","back":true}],"sum":"모델이 기억하는 게 아니라 매번 통째로 다시 읽는 것이다","loop":{"who":"다음 질문","what":"지난 대화가 또 통째로 붙어 온다"}}},"ai--cosine-similarity":{"definition":"벡터(뜻을 담은 숫자 목록)의 크기는 버리고 방향만 견준다. 값은 -1에서 1 사이에 놓이고, 방향이 같을수록 1에 가까워진다.","analogy":"나침반. 한 사람은 1킬로미터를 갔고 다른 사람은 10킬로미터를 갔어도 둘 다 북동쪽이면 같은 방향이다.","example":"검색창에 두 낱말만 쳤는데 긴 제목의 글이 맨 위에 올라오는 것이 길이를 안 보고 잰 결과다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"값 1은 완전히 같은 방향, 0은 직각이라 무관, -1은 정반대다. 검색에서는 이 값을 그대로 쓰지 않고 어디서 자를지를 정해둔다.\n\n```도해\n층: 나온 점수를 어떻게 읽나\n0.9 이상 :: 거의 같은 내용. 근거로 그대로 쓴다\n0.7 에서 0.9 :: 비슷한 내용. 참고로 붙인다\n0.3 에서 0.7 :: 조금 걸친다. 표시를 달아 보여준다\n0.3 미만 :: 무관하다고 보고 버린다\n= 점수를 그냥 쓰지 않고 어디서 자를지 정하는 것이 검색 품질을 정한다\n```\n\n기준을 높게 잡으면 찾는 문서가 너무 적어 \"관련 정보가 없다\" 는 답이 자주 나오고, 낮게 잡으면 무관한 문서가 섞여 들어가 엉뚱한 답이 나온다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **문서 검색** — 질문 벡터와 저장된 조각들의 각도를 재서 가까운 순으로 몇 개만 모델에 넘긴다.\n- **답변 근거 제한** — 기준값 아래로 떨어진 조각은 아예 빼서 지어낸 답이 나올 여지를 줄인다.\n- **비슷한 문서 묶기** — 이미 있는 문서끼리 각도를 재면 주제가 같은 것들이 한데 모인다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **0.5면 절반쯤 맞다는 뜻이다** — 비율이 아니라 각도의 코사인 값이다. 차원이 높으면 무관한 문장들도 0.1에서 0.3 사이에 몰리기 때문에 0.5는 생각보다 가까운 축이다.\n- **점수가 높으면 답이 그 안에 있다** — 방향이 비슷하다는 뜻이지 질문에 답한다는 뜻이 아니다. 주제만 같고 답은 없는 조각도 높게 나온다.\n- **긴 문서가 짧은 문서보다 유리하다** — 크기를 지우고 방향만 보기 때문에 길이는 점수에 들어가지 않는다. 그러려고 각도를 쓰는 것이다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **음수는 반대 의미라기보다 대개 무관이다.** 검색에서는 둘 다 버리는 쪽으로 다룬다.\n- **차원이 높으면 점수가 좁은 구간에 몰린다.** 768차원쯤 되면 대부분의 벡터가 직각에 가까워서 기준값을 그대로 옮겨 쓰면 아무것도 안 걸린다."}],"figure":"```도해\n흐름: 짧은 질문으로 긴 문서를 어떻게 찾아내나\n질문 :: 문장을 벡터로 바꾼다\n문서 벡터 :: 미리 바꿔둔 조각들이 늘어서 있다\n각도 :: 질문과 각 조각 사이의 각도를 잰다\n점수 :: 각도가 좁을수록 1 에 가까워진다\n상위 몇 개 :: 점수 높은 순으로 골라 넘긴다\n= 길이가 아니라 방향을 보기 때문에 짧은 질문이 긴 문서를 찾아낸다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 같은 뜻인데 길이가 다른 두 글을 어떻게 견주나\n직선 거리로 || 각도로\n긴 문서 :: 멀다고 나온다 || 방향이 같다\n짧은 질문 :: 매칭이 안 된다 || 그대로 걸린다\n판정 기준 :: 크기에 흔들림 || 크기와 무관\n= 재는 것을 거리에서 방향으로 바꾸면 길이 차이가 사라진다\n```\n\n\"육아휴직\" 이라는 짧은 질문과 \"육아휴직 신청 방법 절차 안내\" 라는 긴 문서를 벡터로 바꾸면 방향은 비슷한데 크기가 크게 다르다. 두 점 사이의 직선 거리를 재면 멀다는 답이 나온다.\n\n각도는 크기에 흔들리지 않는다. 두 벡터를 같은 길이로 놓고 보면 남는 것은 어느 쪽을 향하느냐뿐이라, 문서가 길든 짧든 뜻만 비슷하면 걸린다."},"recap":"Cosine Similarity는 두 벡터의 크기를 버리고 방향만 견주는 값이다. 문서 길이가 점수에 들어가지 않아서 짧은 질문으로 긴 문서를 찾는 데 쓰인다. 점수 자체보다 어디서 자를지를 정하는 일이 검색 결과를 좌우한다.","check":[{"q":"한 줄짜리 질문이 열 쪽짜리 문서를 찾아낼 수 있는 이유는","at":"해결하는 문제"},{"q":"기준값을 0.9로 올려 잡으면 어떤 답이 자주 나오게 되나","at":"작동 원리"},{"q":"유사도가 0.9인데도 질문에 대한 답이 그 조각에 없을 수 있는 이유는","at":"흔한 오해"}],"myths":[{"wrong":"0.5면 절반쯤 맞다는 뜻이다","right":"비율이 아니라 각도의 코사인 값이다. 차원이 높으면 무관한 문장들도 0.1에서 0.3 사이에 몰리기 때문에 0.5는 생각보다 가까운 축이다."},{"wrong":"점수가 높으면 답이 그 안에 있다","right":"방향이 비슷하다는 뜻이지 질문에 답한다는 뜻이 아니다. 주제만 같고 답은 없는 조각도 높게 나온다."},{"wrong":"긴 문서가 짧은 문서보다 유리하다","right":"크기를 지우고 방향만 보기 때문에 길이는 점수에 들어가지 않는다. 그러려고 각도를 쓰는 것이다."}],"cases":[{"label":"문서 검색","note":"질문 벡터와 저장된 조각들의 각도를 재서 가까운 순으로 몇 개만 모델에 넘긴다."},{"label":"답변 근거 제한","note":"기준값 아래로 떨어진 조각은 아예 빼서 지어낸 답이 나올 여지를 줄인다."},{"label":"비슷한 문서 묶기","note":"이미 있는 문서끼리 각도를 재면 주제가 같은 것들이 한데 모인다."}],"dia":{"shape":"흐름","title":"짧은 질문으로 긴 문서를 어떻게 찾아내나","rows":[{"who":"질문","what":"문장을 벡터로 바꾼다"},{"who":"문서 벡터","what":"미리 바꿔둔 조각들이 늘어서 있다"},{"who":"각도","what":"질문과 각 조각 사이의 각도를 잰다"},{"who":"점수","what":"각도가 좁을수록 1 에 가까워진다"},{"who":"상위 몇 개","what":"점수 높은 순으로 골라 넘긴다"}],"sum":"길이가 아니라 방향을 보기 때문에 짧은 질문이 긴 문서를 찾아낸다"}},"ai--embedding":{"definition":"컴퓨터는 \"강아지\"와 \"개\"가 비슷한 말인지 모른다. 두 단어를 각각 수백 개의 숫자로 바꾸되, 뜻이 가까우면 숫자도 가깝게 만든다. 그러면 뜻을 계산으로 비교할 수 있다.","analogy":"지도 위의 좌표. 도시 이름만으로는 어디가 가까운지 모르지만 위도와 경도로 바꾸면 거리를 뺄셈으로 구할 수 있다. 임베딩은 뜻에 좌표를 붙이는 일이다.","example":"사진첩 검색창에 바다라고 치면 이름에 바다가 없는 사진들이 올라오는 그 일이다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"임베딩이 만들어낸 숫자 목록을 벡터라고 부른다. 벡터 사이의 거리는 보통 각도로 잰다. 이걸 코사인 유사도라고 하고, 1에 가까울수록 뜻이 가깝다.\n\n넣을 수 있는 것은 글만이 아니다.\n\n- **단어** — \"강아지\" 하나\n- **문장** — \"강아지가 공을 물었다\"\n- **문단** — 문서 조각 하나\n- **이미지** — 사진도 같은 공간에 넣을 수 있다\n\n같은 공간에 넣으면 글로 이미지를 검색하는 일도 가능해진다.\n\n중요한 제약이 있다. **같은 모델로 만든 벡터끼리만 비교할 수 있다.** 문서를 A 모델로 임베딩했다면 질문도 A 모델로 해야 한다. 모델을 바꾸면 저장된 벡터를 전부 다시 만들어야 한다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **의미 검색** — 사용자가 쓴 표현과 문서의 표현이 달라도 찾아준다.\n- **추천** — 사용자가 좋아한 항목의 벡터와 가까운 것을 고른다.\n- **중복 탐지** — 표현만 바꾼 문서나 문의를 찾아낸다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **임베딩이 문장의 뜻을 이해한다** — 이해하지 않는다. 같이 등장하는 패턴에서 뽑은 통계라 반대말이 서로 가깝게 나오는 일도 흔하다.\n- **숫자가 많을수록 좋다** — 차원이 크면 정확도가 조금 오르지만 저장 공간과 검색 비용이 같이 오른다.\n- **모델을 바꿔도 기존 벡터를 쓸 수 있다** — 좌표계 자체가 달라진다. 전부 다시 만들어야 한다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **반대말이 가깝게 나온다.** \"좋다\"와 \"나쁘다\"는 같은 문맥에 등장해서 벡터가 가깝다. 감정 판단에 임베딩 거리만 쓰면 틀린다.\n- **모델 교체 비용을 미리 계산한다.** 문서 백만 건이면 백만 번 다시 임베딩해야 한다."}],"figure":"```도해\n흐름: 비슷한 문서를 찾을 때 무슨 계산을 하나\n문장 :: \"환불하고 싶어요\" 가 들어온다\n임베딩 모델 :: 숫자 1536개짜리 목록으로 바꾼다\n저장된 문서 :: 이미 같은 방식으로 바뀌어 있다\n거리 계산 :: 두 목록이 이루는 각도를 잰다\n결과 :: 각도가 가장 작은 문서가 뜻이 가장 가깝다\n= 단어가 하나도 안 겹쳐도 뜻이 가까우면 찾아낸다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: \"환불\" 로 검색하면 무엇이 나오나\n키워드 검색 || 임베딩 검색\n\"반품 절차\" 문서 :: 못 찾는다 || 찾는다\n\"환불 불가\" 문서 :: 찾는다 || 찾는다\n오타 \"환뷸\" :: 못 찾는다 || 대체로 찾는다\n= 글자가 겹치는지가 아니라 뜻이 가까운지로 찾게 만든다\n```\n\n키워드 검색은 글자가 겹쳐야 찾는다. \"환불\"로 검색하면 \"반품 절차\"라는 제목의 문서는 나오지 않는다. 같은 말을 다르게 쓰는 경우가 워낙 많아서 사용자는 원하는 문서를 찾지 못한다.\n\n임베딩은 뜻을 좌표로 만들어 이 문제를 우회한다. 글자가 하나도 겹치지 않아도 뜻이 가까우면 좌표가 가깝다."},"recap":"Embedding은 뜻을 좌표로 바꿔 계산으로 비교할 수 있게 만드는 방법이다. 글자가 안 겹쳐도 찾아주지만, 같은 모델로 만든 벡터끼리만 비교할 수 있다.","check":[{"q":"\"환불\"로 검색했는데 \"반품 절차\" 문서가 나오는 것이 어떻게 가능한가","at":"해결하는 문제"},{"q":"임베딩 모델을 바꾸면 무슨 작업이 따라오나","at":"작동 원리"},{"q":"리뷰의 좋고 나쁨을 임베딩 거리로만 판단하면 왜 위험한가","at":"주의사항"}],"myths":[{"wrong":"임베딩이 문장의 뜻을 이해한다","right":"이해하지 않는다. 같이 등장하는 패턴에서 뽑은 통계라 반대말이 서로 가깝게 나오는 일도 흔하다."},{"wrong":"숫자가 많을수록 좋다","right":"차원이 크면 정확도가 조금 오르지만 저장 공간과 검색 비용이 같이 오른다."},{"wrong":"모델을 바꿔도 기존 벡터를 쓸 수 있다","right":"좌표계 자체가 달라진다. 전부 다시 만들어야 한다."}],"cases":[{"label":"의미 검색","note":"사용자가 쓴 표현과 문서의 표현이 달라도 찾아준다."},{"label":"추천","note":"사용자가 좋아한 항목의 벡터와 가까운 것을 고른다."},{"label":"중복 탐지","note":"표현만 바꾼 문서나 문의를 찾아낸다."}],"dia":{"shape":"흐름","title":"비슷한 문서를 찾을 때 무슨 계산을 하나","rows":[{"who":"문장","what":"\"환불하고 싶어요\" 가 들어온다"},{"who":"임베딩 모델","what":"숫자 1536개짜리 목록으로 바꾼다"},{"who":"저장된 문서","what":"이미 같은 방식으로 바뀌어 있다"},{"who":"거리 계산","what":"두 목록이 이루는 각도를 잰다"},{"who":"결과","what":"각도가 가장 작은 문서가 뜻이 가장 가깝다"}],"sum":"단어가 하나도 안 겹쳐도 뜻이 가까우면 찾아낸다"}},"ai--escalation":{"definition":"넘길 길이 없으면 AI는 모르는 것도 답하려 든다. 확신이 낮거나 권한이 필요하거나 사용자가 이미 화가 나 있으면, 계속 붙잡고 있는 것보다 담당자에게 넘기는 편이 낫다.","analogy":"신입 상담원이 모르는 질문을 받으면 선배를 부르는 것. 억지로 답하는 쪽이 더 큰일을 만든다.","example":"상담 챗봇 창에서 상담원 연결을 누르면 사람이 이어받는데, 그 넘어가는 자리가 여기다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"넘길지 말지는 대개 네 가지를 본다.\n\n- **확신도** 답의 확신도가 정해둔 값 아래로 떨어지면 넘긴다.\n- **반복 실패** 같은 요청을 정해둔 횟수만큼 못 풀면 넘긴다.\n- **명시적 요청** 담당자나 상담원을 찾는 말이 나오면 바로 넘긴다.\n- **부정적 감정** 화가 드러난 표현이 보이면 우선순위를 올려 넘긴다.\n\n넘길 때는 대화 내용을 담은 티켓을 만들고 담당자에게 알린다. 티켓에는 왜 넘겨졌는지를 함께 적어야 받는 사람이 처음부터 다시 묻지 않는다. 넘긴 사유에 따라 응답 목표 시간을 다르게 잡는데, 감정이 드러난 건은 시스템 장애 다음으로 급하게 다룬다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **권한이 필요한 요청** — 승인 권한이 없는 일은 티켓을 만들고 담당자가 이어받는다.\n- **자료에 없는 질문** — 근거 문서를 못 찾으면 지어내지 않고 넘긴다.\n- **불만이 드러난 대화** — 화가 난 표현이 보이면 안내를 더 하지 않고 바로 연결한다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **에스컬레이션은 AI 가 실패했다는 표시다** — 설계에 들어 있는 정상 경로다. 넘길 줄 모르고 계속 답을 지어내는 쪽이 실패한 것이다.\n- **정확도를 올리면 필요 없어진다** — 승인이나 예외 처리처럼 권한이 걸린 일은 정확도와 상관없이 사람이 정해야 한다.\n- **답을 못 찾을 때만 넘기면 된다** — 사용자가 담당자를 찾거나 화가 나 있을 때도 넘긴다. 답을 아는지와 지금 넘겨야 하는지는 다른 문제다."}],"figure":"```도해\n흐름: 답을 못 찾은 대화는 어디로 가나\n사용자 :: 규정에 관해 묻는다\nAI :: 근거를 못 찾고 확신도 낮다\n판정 :: 넘길 조건에 걸리는지 본다\n티켓 :: 대화 내용을 담아 티켓을 만든다\n< 담당자 :: 사람이 이어받아 답한다\n= 못 하는 것을 빨리 인정하는 쪽이 사용자를 덜 지치게 한다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 넘기는 길이 없으면 대화가 어떻게 되나\n넘기지 않으면 || 넘기면\n같은 질문 :: 계속 못 찾는다 || 사람이 받는다\n답의 정확도 :: 억지로 지어냄 || 모른다고 말함\n화난 사용자 :: 안내만 반복 || 바로 연결\n= 한계를 인정하는 통로가 있어야 대화가 끝날 수 있다\n```\n\nAI가 답을 못 찾았을 때 가장 나쁜 결과는 대화가 안 끝나는 것이다. 사용자는 같은 질문을 표현만 바꿔 다시 묻고, AI는 같은 자료를 다시 뒤진다. 이 반복이 길어질수록 사용자는 그 창구 자체를 안 쓰게 된다.\n\n에스컬레이션은 그 반복에 끝을 만든다. 몇 번 실패하면 사람에게 넘긴다는 규칙이 있으면, 사용자는 적어도 다음에 무슨 일이 일어날지 알게 된다."},"recap":"Escalation은 AI가 감당하지 못하는 대화를 사람에게 넘기는 절차다. 확신도와 반복 실패와 사용자의 요청과 감정을 보고 판단하며, 넘긴 사유를 함께 전달해야 받는 쪽이 이어서 처리할 수 있다.","check":[{"q":"사용자가 같은 질문을 표현만 바꿔 계속 묻는 상황에서 무엇이 빠져 있나","at":"해결하는 문제"},{"q":"답을 정확히 알고 있는데도 넘겨야 하는 경우는 어떤 때인가","at":"흔한 오해"},{"q":"티켓에 넘긴 사유를 적어야 하는 이유가 무엇인가","at":"작동 원리"}],"myths":[{"wrong":"에스컬레이션은 AI 가 실패했다는 표시다","right":"설계에 들어 있는 정상 경로다. 넘길 줄 모르고 계속 답을 지어내는 쪽이 실패한 것이다."},{"wrong":"정확도를 올리면 필요 없어진다","right":"승인이나 예외 처리처럼 권한이 걸린 일은 정확도와 상관없이 사람이 정해야 한다."},{"wrong":"답을 못 찾을 때만 넘기면 된다","right":"사용자가 담당자를 찾거나 화가 나 있을 때도 넘긴다. 답을 아는지와 지금 넘겨야 하는지는 다른 문제다."}],"cases":[{"label":"권한이 필요한 요청","note":"승인 권한이 없는 일은 티켓을 만들고 담당자가 이어받는다."},{"label":"자료에 없는 질문","note":"근거 문서를 못 찾으면 지어내지 않고 넘긴다."},{"label":"불만이 드러난 대화","note":"화가 난 표현이 보이면 안내를 더 하지 않고 바로 연결한다."}],"dia":{"shape":"흐름","title":"답을 못 찾은 대화는 어디로 가나","rows":[{"who":"사용자","what":"규정에 관해 묻는다"},{"who":"AI","what":"근거를 못 찾고 확신도 낮다"},{"who":"판정","what":"넘길 조건에 걸리는지 본다"},{"who":"티켓","what":"대화 내용을 담아 티켓을 만든다"},{"who":"담당자","what":"사람이 이어받아 답한다","back":true}],"sum":"못 하는 것을 빨리 인정하는 쪽이 사용자를 덜 지치게 한다"}},"ai--fallback":{"definition":"찾던 곳에 답이 없거나 그 쪽이 응답하지 않을 때, 빈손으로 끝내는 대신 다음 순서로 정해둔 곳에 다시 물어본다. 어디까지 내려갈지와 끝까지 실패하면 무엇을 돌려줄지를 미리 정해두는 것이 폴백 설계다.","analogy":"편의점에 찾던 음료가 없으면 옆 가게로 가고, 거기도 없으면 비슷한 걸 사는 것과 같다.","example":"휴대폰 지문 인식이 두어 번 실패하면 비밀번호 입력 화면이 뜨는 그 자리다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"순서를 정하는 기준은 대개 빠르고 정확한 것부터다. 미리 정리된 FAQ가 있으면 그것부터 보고, 없으면 문서 검색으로, 그것도 없으면 더 넓은 곳으로 내려간다. 아래로 갈수록 답을 찾을 확률은 올라가고 정확도는 떨어진다.\n\n여기서 까다로운 것은 \"실패\"를 무엇으로 볼지다. 오류가 난 경우는 명확하지만, 응답이 오긴 왔는데 \"찾을 수 없습니다\"인 경우도 실패로 봐야 한다. 이걸 성공으로 처리하면 체인은 첫 단계에서 멈추고 아래 순서는 영영 쓰이지 않는다.\n\n질문 종류마다 순서를 따로 두기도 한다. 사내 규정을 묻는 질문과 화면 위치를 묻는 질문은 뒤져야 할 곳이 다르기 때문이다."},{"slot":"compare","label":"무엇과 비교되나","head":"📊 비교: 폴백과 에스컬레이션","body":"| | 폴백 | 에스컬레이션 |\n|---|---|---|\n| 하는 일 | 다른 방법으로 다시 시도 | 사람에게 넘김 |\n| 사람 개입 | 없다 | 필요하다 |\n| 언제 | 한 방법이 실패했을 때 | 방법이 다 떨어졌을 때 |\n| 비용 | 낮다 | 높다 |"},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **답변 체인** — FAQ에 없으면 사내 문서를 뒤지고, 거기에도 없으면 더 일반적인 답변으로 내려간다.\n- **응답이 늦을 때** — 정해둔 시간 안에 답이 안 오면 기다리지 않고 다음 순서로 넘긴다.\n- **최종 문구** — 전부 실패하면 \"찾지 못했다\"와 함께 다음에 어디로 가면 되는지를 같이 알려준다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **폴백은 그냥 다시 시도하는 것이다** — 같은 곳에 다시 묻는 건 재시도다. 폴백은 다른 곳에 묻는 것이고, 안 되는 곳을 계속 두드리지 않는다는 점이 다르다.\n- **폴백을 많이 걸어둘수록 좋다** — 순서가 길어지면 실패할 때마다 시간이 쌓인다. 마지막 순서까지 갔을 때 사용자가 얼마나 기다리게 되는지가 실제 상한이다.\n- **폴백이 있으면 장애가 안 보인다** — 안 보이는 게 문제다. 아래 순서로 계속 내려가고 있다는 사실을 기록해두지 않으면 1순위가 죽은 채로 오래 방치된다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **아래로 내려갈수록 답의 근거가 약해진다.** 어느 순서에서 나온 답인지 사용자에게 알려주지 않으면, 확실한 답과 대충 맞는 답이 같은 얼굴로 나간다.\n- **모든 실패를 같게 다루지 않는다.** 자료가 없어서 못 찾은 것과 서비스가 죽어서 못 받은 것은 다음 대응이 달라야 한다."}],"figure":"```도해\n흐름: 첫 번째가 답을 못 주면 무슨 일이 일어나나\n질문 :: 사용자가 규정을 물어본다\n1순위 :: FAQ 에서 찾는다. 없다\n2순위 :: 문서 검색으로 넘어간다. 찾았다\n최종 :: 여기까지도 못 찾으면 정해둔 문구\n< 사용자 :: 어느 순서에서 나왔든 답을 하나 받는다\n= 실패를 끝이 아니라 다음 순서로 넘어가는 신호로 쓴다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 첫 시도가 실패하면 어떻게 되나\n폴백 없이 || 폴백으로\n답 없음 :: 빈 화면 || 다음에 물어봄\n한 곳 장애 :: 전체 멈춤 || 그 순서만 건너뜀\n사용자 :: 그냥 떠남 || 어떻게든 받음\n= 한 곳의 실패를 전체의 실패로 만들지 않는 장치다\n```\n\n정보를 한 곳에서만 찾으면 그 한 곳의 사정이 그대로 결과가 된다. 자료가 아직 안 들어갔거나, 그 서비스가 잠깐 멈췄거나, 응답이 늦으면 사용자에게는 전부 똑같이 \"답이 없다\"로 보인다.\n\n폴백은 그 실패를 신호로 바꾼다. 찾지 못했다는 응답이 오면 다음 순서로 넘어가고, 마지막까지 못 찾으면 그때는 무엇을 돌려줄지 정해둔 문구가 나간다. 실패하더라도 무엇을 받을지가 정해져 있다."},"recap":"Fallback은 첫 방법이 실패했을 때 미리 정해둔 다음 방법으로 넘어가는 구조다. 순서를 정하는 일보다 무엇을 실패로 볼지, 끝까지 실패하면 무엇을 돌려줄지를 정하는 일이 실제 설계다. 내려가고 있다는 사실을 남기지 않으면 장애가 조용히 묻힌다.","check":[{"q":"1순위가 \"찾을 수 없습니다\"라고 답했을 때 이걸 성공으로 처리하면 무슨 일이 벌어지나","at":"작동 원리"},{"q":"재시도만 걸어두는 것과 폴백을 두는 것은 무엇이 다른가","at":"흔한 오해"},{"q":"폴백 순서를 아래까지 내려가서 받은 답은 무엇이 약한가","at":"주의사항"}],"myths":[{"wrong":"폴백은 그냥 다시 시도하는 것이다","right":"같은 곳에 다시 묻는 건 재시도다. 폴백은 다른 곳에 묻는 것이고, 안 되는 곳을 계속 두드리지 않는다는 점이 다르다."},{"wrong":"폴백을 많이 걸어둘수록 좋다","right":"순서가 길어지면 실패할 때마다 시간이 쌓인다. 마지막 순서까지 갔을 때 사용자가 얼마나 기다리게 되는지가 실제 상한이다."},{"wrong":"폴백이 있으면 장애가 안 보인다","right":"안 보이는 게 문제다. 아래 순서로 계속 내려가고 있다는 사실을 기록해두지 않으면 1순위가 죽은 채로 오래 방치된다."}],"cases":[{"label":"답변 체인","note":"FAQ에 없으면 사내 문서를 뒤지고, 거기에도 없으면 더 일반적인 답변으로 내려간다."},{"label":"응답이 늦을 때","note":"정해둔 시간 안에 답이 안 오면 기다리지 않고 다음 순서로 넘긴다."},{"label":"최종 문구","note":"전부 실패하면 \"찾지 못했다\"와 함께 다음에 어디로 가면 되는지를 같이 알려준다."}],"dia":{"shape":"흐름","title":"첫 번째가 답을 못 주면 무슨 일이 일어나나","rows":[{"who":"질문","what":"사용자가 규정을 물어본다"},{"who":"1순위","what":"FAQ 에서 찾는다. 없다"},{"who":"2순위","what":"문서 검색으로 넘어간다. 찾았다"},{"who":"최종","what":"여기까지도 못 찾으면 정해둔 문구"},{"who":"사용자","what":"어느 순서에서 나왔든 답을 하나 받는다","back":true}],"sum":"실패를 끝이 아니라 다음 순서로 넘어가는 신호로 쓴다"}},"ai--few-shot-zero-shot-learning":{"definition":"모델을 다시 학습시키지 않고 프롬프트만으로 새 작업을 시킨다. 예시가 없으면 Zero-shot, 두어 개면 Few-shot, 수십 개를 넘어가면 Many-shot이라 부른다.","analogy":"새로 온 사람에게 일을 넘길 때, 말로만 설명하는 것과 처리해둔 서류 두어 장을 같이 건네는 것의 차이다.","example":"엑셀에서 두어 칸을 직접 채우고 아래로 끌면 나머지가 같은 모양으로 채워진다. 채워둔 두 칸이 형식을 정한 것이다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"예시는 모델 안에 남지 않는다. 그 요청에 붙어 간 글일 뿐이고, 다음 요청에는 다시 붙여야 한다. 모델은 예시에서 두 가지를 읽는다. 답을 어떤 형식으로 쓸지, 그리고 경계에 걸치는 입력을 어느 쪽으로 볼지.\n\n```\n다음 예시처럼 분류하세요.\n\n문장: \"정말 최고예요!\"   감정: 긍정\n문장: \"실망스럽네요\"     감정: 부정\n문장: \"보통이에요\"       감정: 중립\n\n이제 분류하세요.\n문장: {입력}\n감정:\n```\n\n개수를 늘릴수록 정확해지지만 토큰과 비용도 같이 늘어난다. 보통 서너 개 근처에서 더 넣어도 나아지는 폭이 크게 줄어든다."},{"slot":"compare","label":"무엇과 비교되나","head":"📊 비교","body":"| | 예시 개수 | 토큰 | 잘 맞는 곳 |\n|---|---|---|---|\n| Zero-shot | 0개 | 적다 | 감정 분류, 요약, 번역처럼 흔한 작업 |\n| Few-shot | 2~10개 | 많다 | 정해진 형식이나 특정 분야의 답 |\n| Many-shot | 수십~수백 개 | 아주 많다 | 규칙이 복잡해 말로 설명하기 어려운 것 |"},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **답변 형식 맞추기** — 근거 조항을 앞에 붙인 답변을 예시로 두면 이후 답도 같은 모양으로 나온다.\n- **애매한 경계 정하기** — 어중간한 문장을 예시에 넣어 어디까지가 긍정이고 어디부터 중립인지 정해준다.\n- **풀이 과정 보이기** — 단계별로 계산한 예시를 넣으면 답만 던지지 않고 과정을 따라 쓴다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **Few-shot은 모델을 학습시키는 것이다** — 모델은 그대로다. 예시는 그 요청 한 번에만 붙어 있는 글이라 다음 요청에는 다시 붙여야 한다.\n- **예시가 많을수록 좋다** — 토큰과 비용이 따라 늘고 컨텍스트 창을 밀어낸다. 서너 개를 넘어가면 늘린 만큼 나아지지 않는다.\n- **Zero-shot은 예시를 못 넣어서 쓰는 것이다** — 흔한 작업에서는 예시 없이도 답이 나오고 그만큼 싸고 빠르다. 예시는 형식이나 기준이 특이할 때 붙인다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **예시가 서로 비슷하면 낭비다.** 같은 유형을 세 번 보여주는 대신 수량을 묻는 것, 절차를 묻는 것, 자격을 묻는 것처럼 다른 유형을 섞는다.\n- **예시끼리 형식이 어긋나면 답도 어긋난다.** 어떤 예시는 근거를 쓰고 어떤 예시는 안 쓰면 모델은 둘 중 아무거나 고른다.\n- **예시도 컨텍스트 창을 먹는다.** 예시를 백 개까지 늘리면 정작 넣어야 할 문서가 들어갈 자리가 없어진다."}],"figure":"```도해\n흐름: 예시를 붙이면 답이 왜 달라지나\n프롬프트 :: \"이 문장의 감정을 분류해줘\"\n예시 :: \"최고예요 → 긍정\" 을 두어 개 붙인다\n모델 :: 예시에서 답의 형태와 기준을 읽는다\n답 :: 예시와 같은 모양으로 돌려준다\n@ 다음 요청 :: 예시를 또 붙여야 한다. 토큰도 매번\n= 예시는 새로 배우게 하는 게 아니라 답의 틀을 정해주는 것이다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 새 작업을 시키려면 무엇이 필요한가\n따로 학습시켜서 || 예시를 붙여서\n준비물 :: 데이터 수천 건 || 예시 두세 개\n착수 :: 학습을 돌린다 || 바로 쓴다\n바꾸려면 :: 다시 학습 || 예시만 고침\n= 모델을 건드리지 않고 프롬프트 안에서 끝내는 것이 요점이다\n```\n\n전통적인 기계학습은 새 작업마다 수천에서 수만 건의 학습 데이터를 모아야 했다. Fine-tuning으로 줄여도 최소 50~100개 예시가 들고, 기준이 바뀌면 다시 학습을 돌려야 한다.\n\n프롬프트에 예시를 붙이는 방식은 그 준비를 건너뛴다. 기준이 바뀌면 예시 문장을 고치면 되고, 반영은 다음 요청부터 곧바로 된다."},"recap":"Zero-shot은 지시만 주는 것이고 Few-shot은 예시를 몇 개 붙여주는 것이다. 예시는 모델을 가르치는 장치가 아니라 그 요청 안에서 답의 형식과 기준을 정해주는 장치다. 형식이 특이하거나 경계가 애매할 때만 붙이고, 개수는 서너 개에서 멈추는 편이 낫다.","check":[{"q":"Few-shot으로 잘 나오던 형식이 다음 요청에서 흐트러졌다. 예시를 다시 안 붙였다면 왜 그런가","at":"작동 원리"},{"q":"예시를 3개에서 30개로 늘렸는데 비용만 늘고 답은 그대로다. 무엇을 잘못 본 건가","at":"흔한 오해"},{"q":"감정 분류처럼 흔한 작업에 굳이 예시를 안 붙여도 되는 이유는","at":"비교"}],"myths":[{"wrong":"Few-shot은 모델을 학습시키는 것이다","right":"모델은 그대로다. 예시는 그 요청 한 번에만 붙어 있는 글이라 다음 요청에는 다시 붙여야 한다."},{"wrong":"예시가 많을수록 좋다","right":"토큰과 비용이 따라 늘고 컨텍스트 창을 밀어낸다. 서너 개를 넘어가면 늘린 만큼 나아지지 않는다."},{"wrong":"Zero-shot은 예시를 못 넣어서 쓰는 것이다","right":"흔한 작업에서는 예시 없이도 답이 나오고 그만큼 싸고 빠르다. 예시는 형식이나 기준이 특이할 때 붙인다."}],"cases":[{"label":"답변 형식 맞추기","note":"근거 조항을 앞에 붙인 답변을 예시로 두면 이후 답도 같은 모양으로 나온다."},{"label":"애매한 경계 정하기","note":"어중간한 문장을 예시에 넣어 어디까지가 긍정이고 어디부터 중립인지 정해준다."},{"label":"풀이 과정 보이기","note":"단계별로 계산한 예시를 넣으면 답만 던지지 않고 과정을 따라 쓴다."}],"dia":{"shape":"흐름","title":"예시를 붙이면 답이 왜 달라지나","rows":[{"who":"프롬프트","what":"\"이 문장의 감정을 분류해줘\""},{"who":"예시","what":"\"최고예요 → 긍정\" 을 두어 개 붙인다"},{"who":"모델","what":"예시에서 답의 형태와 기준을 읽는다"},{"who":"답","what":"예시와 같은 모양으로 돌려준다"}],"sum":"예시는 새로 배우게 하는 게 아니라 답의 틀을 정해주는 것이다","loop":{"who":"다음 요청","what":"예시를 또 붙여야 한다. 토큰도 매번"}}},"ai--fine-tuning":{"definition":"모델을 처음부터 만드는 데는 막대한 데이터와 계산이 든다. 파인튜닝은 이미 언어를 아는 모델에 우리 예시 수백 개를 더 보여줘서 답하는 방식만 바꾼다.","analogy":"이미 의사 면허가 있는 사람에게 한 분야만 더 수련시키는 것이다. 의학을 처음부터 가르치지 않는다.","example":"몇 달 쓴 휴대폰 자판이 내가 자주 쓰는 말투부터 먼저 띄워주게 되는 그 변화와 결이 같다.","sections":[{"slot":"compare","label":"무엇과 비교되나","head":"📊 비교","body":"| | 프롬프트 | RAG | 파인튜닝 |\n|---|---|---|---|\n| 준비 | 바로 | 문서를 넣어두면 됨 | 예시 수백 개 |\n| 반영 시점 | 즉시 | 즉시 | 재학습 후 |\n| 잘 맞는 것 | 일반 작업 | 자주 바뀌는 정보 | 고정된 형식과 말투 |\n| 바뀌면 | 문장만 고친다 | 문서만 갈아 끼운다 | 처음부터 다시 |"},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **정해진 답변 형식** — 상담 답변을 늘 같은 구조로 뽑아야 할 때 그 형식의 예시로 학습시킨다.\n- **전문 분야 번역** — 법률이나 의료 용어 번역 쌍을 학습시켜 용어 선택을 일정하게 만든다.\n- **회사 코드 스타일** — 사내 코드 리뷰 기록을 학습시켜 제안하는 코드의 모양을 맞춘다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **파인튜닝하면 모델이 우리 문서를 기억한다** — 기억하지 못한다. 옮겨지는 건 답하는 방식이고, 사실을 정확히 인용하게 하려면 문서를 그때그때 찾아 넣어주는 방식이 맞다.\n- **데이터가 많을수록 무조건 좋다** — 양보다 일관성이다. 같은 질문에 서로 다른 형식의 답이 섞여 있으면 모델은 어느 쪽도 제대로 배우지 않는다.\n- **한 번 학습시키면 계속 최신 상태다** — 학습한 시점에서 멈춘다. 규정이 바뀌면 예시를 고쳐 다시 학습시켜야 하고 그때마다 비용이 다시 든다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **예시가 적으면 흉내만 낸다.** 수가 부족하면 학습 예시에만 잘 맞고 조금 다른 질문에는 오히려 나빠진다.\n- **바뀌는 정보에는 쓰지 않는다.** 규정이나 가격처럼 자주 고쳐지는 내용은 학습이 아니라 문서 조회로 다뤄야 한다."}],"figure":"```도해\n흐름: 우리 회사 말투로 답하게 만들려면 무슨 순서로 하나\n예시 모으기 :: 질문과 원하는 답을 짝지어 수백 개 만든다\n형식 맞추기 :: 정해진 형식의 파일로 정리한다\n추가 학습 :: 기존 모델의 값을 그 예시 쪽으로 조금씩 옮긴다\n새 모델 :: 우리 예시를 닮은 모델이 하나 나온다\n사용 :: 긴 지시문 없이 질문만 보내도 그 말투로 답한다\n@ 내용이 바뀌면 :: 예시를 고쳐 처음부터 다시 돌린다\n= 지식을 넣는다기보다 답하는 방식을 옮기는 작업이다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 매번 긴 지시문을 붙여 쓰면 어떻게 되나\n지시문으로 || 파인튜닝으로\n요청 길이 :: 매번 길어진다 || 질문만 보낸다\n말투 :: 들쭉날쭉하다 || 일정하다\n비용 구조 :: 요청마다 낸다 || 학습에 한 번\n= 매 요청에 붙이던 것을 모델 안으로 옮기는 것이다\n```\n\n같은 지시문을 매 요청마다 앞에 붙이면 그만큼 토큰을 쓴다. 요청이 많아지면 이 비용이 계속 쌓이고, 지시문이 길어도 모델이 매번 똑같이 따르지는 않는다.\n\n파인튜닝은 그 지시를 예시로 바꿔 모델에 새겨 넣는다. 그다음부터는 짧은 질문만 보내도 학습시킨 형식대로 답한다. 대신 내용이 바뀌면 다시 학습시켜야 한다."},"recap":"Fine-tuning은 이미 학습된 모델에 예시를 더 먹여 답하는 방식을 옮기는 작업이다. 형식과 말투를 고정하는 데는 잘 듣지만, 자주 바뀌는 사실을 넣는 용도로는 맞지 않는다.","check":[{"q":"자주 바뀌는 사내 규정을 파인튜닝으로 넣으면 왜 곤란해지나","at":"주의사항"},{"q":"매 요청에 붙이던 긴 지시문이 사라지면 무엇이 줄어드나","at":"해결하는 문제"},{"q":"예시를 수백 개 모았는데 답 형식이 제각각이면 어떤 결과가 나오나","at":"흔한 오해"}],"myths":[{"wrong":"파인튜닝하면 모델이 우리 문서를 기억한다","right":"기억하지 못한다. 옮겨지는 건 답하는 방식이고, 사실을 정확히 인용하게 하려면 문서를 그때그때 찾아 넣어주는 방식이 맞다."},{"wrong":"데이터가 많을수록 무조건 좋다","right":"양보다 일관성이다. 같은 질문에 서로 다른 형식의 답이 섞여 있으면 모델은 어느 쪽도 제대로 배우지 않는다."},{"wrong":"한 번 학습시키면 계속 최신 상태다","right":"학습한 시점에서 멈춘다. 규정이 바뀌면 예시를 고쳐 다시 학습시켜야 하고 그때마다 비용이 다시 든다."}],"cases":[{"label":"정해진 답변 형식","note":"상담 답변을 늘 같은 구조로 뽑아야 할 때 그 형식의 예시로 학습시킨다."},{"label":"전문 분야 번역","note":"법률이나 의료 용어 번역 쌍을 학습시켜 용어 선택을 일정하게 만든다."},{"label":"회사 코드 스타일","note":"사내 코드 리뷰 기록을 학습시켜 제안하는 코드의 모양을 맞춘다."}],"dia":{"shape":"흐름","title":"우리 회사 말투로 답하게 만들려면 무슨 순서로 하나","rows":[{"who":"예시 모으기","what":"질문과 원하는 답을 짝지어 수백 개 만든다"},{"who":"형식 맞추기","what":"정해진 형식의 파일로 정리한다"},{"who":"추가 학습","what":"기존 모델의 값을 그 예시 쪽으로 조금씩 옮긴다"},{"who":"새 모델","what":"우리 예시를 닮은 모델이 하나 나온다"},{"who":"사용","what":"긴 지시문 없이 질문만 보내도 그 말투로 답한다"}],"sum":"지식을 넣는다기보다 답하는 방식을 옮기는 작업이다","loop":{"who":"내용이 바뀌면","what":"예시를 고쳐 처음부터 다시 돌린다"}}},"ai--guardrail":{"definition":"모델은 시키는 대로 답하려 하기 때문에 위험한 요청도 그대로 처리한다. 그래서 모델 밖에 검사를 따로 세워 들어오는 말과 나가는 말과 하려는 동작을 각각 본다.","analogy":"도로 가드레일. 운전자가 잘못 꺾어도 차가 낭떠러지로 가지 않게 옆을 막아둔다.","example":"댓글에 욕을 적어 올리면 별표로 가려진 채 등록되는 그 순간이다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"| 자리 | 언제 보나 | 무엇을 막나 |\n|---|---|---|\n| 입력 | 요청을 받을 때 | 개인정보 입력, 공격 문자열 |\n| 행동 | 도구를 부르기 전 | 권한 없는 조회와 삭제 |\n| 출력 | 답을 내보내기 전 | 비밀 값과 민감 정보 노출 |\n| 실행 | 작업이 도는 중 | 같은 호출 반복, 끝나지 않는 작업 |\n\n막는 것만으로는 절반이다. 왜 막혔는지 알려주지 않으면 사용자는 시스템이 고장 났다고 여기고 같은 요청을 되풀이한다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **개인정보 입력 차단** — 채팅창에 주민번호 형태의 숫자가 들어오면 처리하지 않고 입력하지 말라고 안내한다.\n- **응답 가리기** — 답에 전화번호나 비밀 값이 섞이면 그 부분을 가린 뒤 내보낸다.\n- **권한 확인** — 급여 데이터를 읽는 동작 앞에서 그 계정에 권한이 있는지 먼저 보고 없으면 실행하지 않는다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **프롬프트에 하지 말라고 써두면 그게 Guardrail이다** — 프롬프트는 부탁이고 Guardrail은 코드로 된 검사다. 모델이 지시를 어기는 경우가 있어서 바깥에 따로 세운다.\n- **입력만 막으면 된다** — 정상적인 질문에도 민감한 값이 답에 섞여 나올 수 있다. 나가는 쪽 검사가 따로 필요하다.\n- **엄격할수록 안전하다** — 정상적인 요청까지 막히면 사람들은 우회로를 찾는다. 명확한 위험은 즉시 막고 애매한 것은 되묻는 편이 낫다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **막힌 시도를 기록으로 남긴다.** 무엇이 얼마나 막혔는지 봐야 규칙이 센지 느슨한지 판단할 수 있다.\n- **차단 이유를 사용자에게 알린다.** 이유 없이 막히면 같은 요청이 반복되고 문의가 늘어난다."}],"figure":"```도해\n흐름: 사용자 말 한 마디가 어디를 거쳐 답이 되나\n입력 검사 :: 개인정보나 공격 문자열이 있나\n모델 :: 통과한 것만 받아 답을 만든다\n행동 검사 :: 조회나 삭제를 할 권한이 있나\n출력 검사 :: 답에 비밀 값이 섞여 있나\n< 사용자 :: 네 자리를 다 통과한 답만 보인다\n= 막는 자리가 여럿이고 자리마다 보는 것이 다르다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 검사 없이 모델 답을 그대로 내보내면 어떻게 되나\nGuardrail 없이 || Guardrail 로\n주민번호 :: 그대로 나감 || 가려서 나감\n권한 밖 조회 :: 그냥 실행됨 || 앞에서 막힘\n공격 문자열 :: 질의로 전달됨 || 입력에서 차단\n= 모델은 요청을 의심하지 않는다. 의심하는 자리를 밖에 둔다\n```\n\n모델은 요청이 정당한지 따지지 않는다. 주민번호를 넣어 조회해 달라고 하면 그대로 조회하고, 전체 급여 목록을 달라고 하면 갖고 있는 만큼 답한다. 답을 잘 만드는 능력과 하면 안 되는 일을 가려내는 능력은 별개다.\n\nGuardrail은 그 판단을 모델 밖에 둔다. 들어오는 말을 먼저 보고, 실행하려는 동작에 권한이 있는지 보고, 나가는 답에 남으면 안 될 것이 섞였는지 본다."},"recap":"Guardrail은 AI가 하면 안 되는 일을 모델 밖에서 걸러내는 검사 장치다. 입력, 행동, 출력, 실행 네 자리에서 보는 것이 각각 다르다. 막는 일과 왜 막혔는지 알리는 일이 함께 가야 한다.","check":[{"q":"프롬프트에 하지 말라고 써두는 것과 Guardrail 은 무엇이 다른가","at":"흔한 오해"},{"q":"입력 검사를 통과한 질문인데도 출력 검사가 필요한 경우는 어떤 것인가","at":"실제 사례"},{"q":"규칙에 걸려 막혔는데 이유를 안 알려주면 사용자는 무엇을 하나","at":"작동 원리"}],"myths":[{"wrong":"프롬프트에 하지 말라고 써두면 그게 Guardrail이다","right":"프롬프트는 부탁이고 Guardrail은 코드로 된 검사다. 모델이 지시를 어기는 경우가 있어서 바깥에 따로 세운다."},{"wrong":"입력만 막으면 된다","right":"정상적인 질문에도 민감한 값이 답에 섞여 나올 수 있다. 나가는 쪽 검사가 따로 필요하다."},{"wrong":"엄격할수록 안전하다","right":"정상적인 요청까지 막히면 사람들은 우회로를 찾는다. 명확한 위험은 즉시 막고 애매한 것은 되묻는 편이 낫다."}],"cases":[{"label":"개인정보 입력 차단","note":"채팅창에 주민번호 형태의 숫자가 들어오면 처리하지 않고 입력하지 말라고 안내한다."},{"label":"응답 가리기","note":"답에 전화번호나 비밀 값이 섞이면 그 부분을 가린 뒤 내보낸다."},{"label":"권한 확인","note":"급여 데이터를 읽는 동작 앞에서 그 계정에 권한이 있는지 먼저 보고 없으면 실행하지 않는다."}],"dia":{"shape":"흐름","title":"사용자 말 한 마디가 어디를 거쳐 답이 되나","rows":[{"who":"입력 검사","what":"개인정보나 공격 문자열이 있나"},{"who":"모델","what":"통과한 것만 받아 답을 만든다"},{"who":"행동 검사","what":"조회나 삭제를 할 권한이 있나"},{"who":"출력 검사","what":"답에 비밀 값이 섞여 있나"},{"who":"사용자","what":"네 자리를 다 통과한 답만 보인다","back":true}],"sum":"막는 자리가 여럿이고 자리마다 보는 것이 다르다"}},"ai--hallucination":{"definition":"없는 논문 제목, 없는 함수 이름, 없는 조항을 자신 있는 말투로 만들어낸다. 거짓말을 하려는 게 아니라, 그럴듯한 다음 단어를 고르는 일을 정직하게 수행한 결과다.","analogy":"시험에서 모르는 문제를 만난 학생이 빈칸을 두는 대신 그럴듯하게 채우는 것. 채워야 한다는 압박만 있고 모른다고 말할 선택지가 없으면 누구나 그렇게 된다.","example":"알려준 책 제목을 그대로 검색창에 넣었는데 그런 책이 없다고 나오는 순간이다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"어디서 잘 나오는지에 규칙성이 있다.\n\n```도해\n층: 어떤 질문에서 환각이 잘 나오나\n최신 정보 :: 학습 이후의 일. 아예 모른다\n좁은 사실 :: 특정 논문, 조항, 사내 규정\n숫자와 인용 :: 형식은 알지만 값은 모른다\n일반 상식 :: 여기서는 잘 안 나온다\n= 아래로 갈수록 안전하다. 위쪽을 물을 때 근거를 붙여야 한다\n```"},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **없는 라이브러리 함수** — 그럴듯한 이름의 함수를 쓴 코드를 준다. 실행해야 없다는 걸 안다.\n- **법 조항 인용** — 조문 번호와 문구를 만들어낸다. 형식이 정확해서 더 위험하다.\n- **인용 출처** — 제목, 저자, 연도가 모두 갖춰진 존재하지 않는 문헌을 만든다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **환각은 고칠 수 있는 버그다** — 다음 토큰을 확률로 고르는 구조에서 나오는 성질이라 완전히 없앨 수 없다. 줄이고 검증할 대상이다.\n- **\"모르면 모른다고 해\"라고 지시하면 해결된다** — 도움은 되지만 모델은 자기가 모른다는 것을 모른다. 확률이 낮아도 가장 높은 후보를 고를 뿐이다.\n- **큰 모델을 쓰면 사라진다** — 줄어들긴 하지만 없어지지 않는다. 오히려 더 그럴듯해져서 알아채기 어려워진다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **형식이 정확할수록 의심한다.** 조문 번호, 논문 연도, 함수 시그니처처럼 형식이 뚜렷한 것이 가장 잘 만들어진다.\n- **사실 확인이 필요한 곳에는 근거를 강제한다.** 출처를 못 찾으면 답하지 말라는 규칙과 [[RAG]]를 같이 쓴다."}],"figure":"```도해\n흐름: 없는 논문 제목이 어떻게 만들어지나\n사용자 :: \"이 주제 논문 알려줘\" 라고 묻는다\n모델 :: 학습에서 본 제목의 생김새를 떠올린다\n모델 :: 이 자리에 올 법한 단어를 하나씩 고른다\n모델 :: 저자 이름과 연도도 그럴듯하게 잇는다\n< 사용자 :: 형식이 완벽한, 존재하지 않는 논문을 받는다\n= 모델에게는 \"지어내기\" 와 \"답하기\" 가 같은 동작이다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"이 항목은 해결하는 문제가 아니라 **다뤄야 할 문제**다.\n\n```도해\n대조: 모르는 것을 물으면 어떻게 되나\n대비 없이 || 근거를 붙이면\n답 :: 그럴듯하게 지어낸다 || 문서를 인용한다\n확인 :: 사람이 일일이 || 출처를 보면 된다\n모를 때 :: 모른다고 안 한다 || 못 찾았다고 한다\n= 지어내지 못하게 막는 게 아니라, 지어낼 필요가 없게 만드는 쪽이 먹힌다\n```\n\n모델은 확률이 높은 문장을 만든다. 확률이 높은 것과 사실인 것은 다른 기준이라, 학습 데이터에 없는 것을 물으면 빈칸을 채우듯 그럴듯한 것을 만든다.\n\n막는 방법은 모델을 다그치는 게 아니라 근거를 주는 것이다. [[RAG]]로 실제 문서를 함께 넣으면 지어낼 자리가 줄어들고, 출처를 붙이게 하면 사람이 확인할 수 있다."},"recap":"Hallucination은 모델이 사실이 아닌 것을 사실처럼 말하는 현상이다. 구조에서 나오는 성질이라 없앨 수는 없고, 근거를 주고 출처를 붙이게 해서 줄이고 확인하는 것이 대응이다.","check":[{"q":"모델이 거짓말을 하려는 것이 아닌데도 없는 논문을 만들어내는 이유는","at":"그림"},{"q":"조문 번호나 함수 이름이 특히 위험한 이유는","at":"주의사항"},{"q":"\"모르면 모른다고 답해\" 라는 지시만으로 부족한 이유는","at":"흔한 오해"}],"myths":[{"wrong":"환각은 고칠 수 있는 버그다","right":"다음 토큰을 확률로 고르는 구조에서 나오는 성질이라 완전히 없앨 수 없다. 줄이고 검증할 대상이다."},{"wrong":"\"모르면 모른다고 해\"라고 지시하면 해결된다","right":"도움은 되지만 모델은 자기가 모른다는 것을 모른다. 확률이 낮아도 가장 높은 후보를 고를 뿐이다."},{"wrong":"큰 모델을 쓰면 사라진다","right":"줄어들긴 하지만 없어지지 않는다. 오히려 더 그럴듯해져서 알아채기 어려워진다."}],"cases":[{"label":"없는 라이브러리 함수","note":"그럴듯한 이름의 함수를 쓴 코드를 준다. 실행해야 없다는 걸 안다."},{"label":"법 조항 인용","note":"조문 번호와 문구를 만들어낸다. 형식이 정확해서 더 위험하다."},{"label":"인용 출처","note":"제목, 저자, 연도가 모두 갖춰진 존재하지 않는 문헌을 만든다."}],"dia":{"shape":"흐름","title":"없는 논문 제목이 어떻게 만들어지나","rows":[{"who":"사용자","what":"\"이 주제 논문 알려줘\" 라고 묻는다"},{"who":"모델","what":"학습에서 본 제목의 생김새를 떠올린다"},{"who":"모델","what":"이 자리에 올 법한 단어를 하나씩 고른다"},{"who":"모델","what":"저자 이름과 연도도 그럴듯하게 잇는다"},{"who":"사용자","what":"형식이 완벽한, 존재하지 않는 논문을 받는다","back":true}],"sum":"모델에게는 \"지어내기\" 와 \"답하기\" 가 같은 동작이다"}},"ai--intent":{"definition":"같은 요청도 사람마다 다르게 말한다. 그 표현들을 미리 정해둔 몇 개의 갈래로 묶어서 어디로 보낼지 정한다.","analogy":"전화 자동 안내. 무슨 말을 하든 결국 인사팀과 재무팀 중 한 곳으로 연결된다.","example":"검색창에 날씨라고만 쳤는데 결과 목록 대신 오늘 기온 카드가 먼저 뜨는 그 판단이다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"분류기는 갈래를 고르면서 얼마나 확실한지도 함께 내놓는다. 이 점수에 기준선을 두고 넘으면 바로 보내고, 못 넘으면 사용자에게 되묻는다. 애매한 것을 억지로 밀어 넣는 것보다 한 번 확인하는 편이 낫기 때문이다.\n\n앞선 대화도 함께 본다. \"얼마나 남았어?\"만 보면 연차인지 급여일인지 계약 기간인지 알 수 없지만, 바로 앞에서 연차 이야기가 오갔다면 정해진다."},{"slot":"compare","label":"무엇과 비교되나","head":"📊 비교","body":"| 방법 | 잘하는 것 | 못하는 것 |\n|---|---|---|\n| 규칙 기반 | 즉시 답하고 결과가 뻔하다 | 표현이 조금만 달라도 못 잡는다 |\n| 학습 모델 기반 | 빠르고 대량 처리에 싸다 | 학습 데이터를 모아야 한다 |\n| LLM 기반 | 맥락과 뉘앙스를 읽는다 | 호출 비용과 지연이 붙는다 |"},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **고객 문의 분류** — 들어온 문의를 갈래로 나눠 담당 창구로 바로 보낸다.\n- **사내 챗봇** — 신청 방법, 규정 확인, 급여 같은 갈래로 나눠 각각 다른 자료를 찾게 한다.\n- **애매한 질문 되묻기** — 점수가 기준에 못 미치면 답을 지어내지 않고 선택지를 보여준다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **의도를 알아냈으면 답도 나온 것이다** — 어디로 보낼지가 정해졌을 뿐이다. 실제 답은 그 갈래를 맡은 쪽이 따로 만든다.\n- **갈래를 많이 만들수록 정확해진다** — 갈래끼리 겹치기 시작하면 분류기가 헷갈린다. 서로 안 겹치게 적게 두는 편이 정확도가 높다.\n- **한 문장만 보면 된다** — 앞선 대화를 안 보면 \"얼마나 남았어?\" 같은 말은 무엇을 묻는지 정할 수 없다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **기준선을 정해둔다.** 점수가 낮은데도 억지로 보내면 엉뚱한 담당이 자신 있게 틀린 답을 낸다.\n- **어디에도 안 맞는 갈래를 하나 둔다.** 모든 말을 정해진 갈래에 밀어 넣으면 처리할 수 없는 요청이 조용히 잘못 처리된다."}],"figure":"```도해\n흐름: \"주소 변경하고 싶어\" 는 어디로 가나\n사용자 :: 자기 말로 요청을 적는다\n분류기 :: 미리 정해둔 갈래에 대응시킨다\n분류기 :: 갈래마다 얼마나 확실한지 점수를 낸다\n판단 :: 점수가 기준을 넘으면 그 갈래로 정한다\n< 담당 :: 정해진 쪽이 답을 만들어 돌려준다\n= 무엇을 원하는지 먼저 정해야 어디로 보낼지가 나온다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 들어온 말을 갈래로 나누지 않으면 어떻게 되나\n분류 없이 || Intent 분류로\n처리 방식 :: 사람이 나눈다 || 즉시 나뉜다\n잘못 보냄 :: 전부 헛돈다 || 한 곳만 실행\n같은 뜻 다른 말 :: 따로 처리 || 한 갈래로\n= 무엇을 원하는지 정하는 자리가 있어야 뒤가 단순해진다\n```\n\n문의가 하루에 수백 건 들어오면 사람이 하나씩 읽어 어느 쪽으로 보낼지 정하는 방식은 느리고 자주 틀린다. 자동으로 넘긴다 해도 갈래를 안 정하면 담당을 전부 돌려보고 그중 맞는 답을 고르게 되어, 시간과 비용이 갈래 수만큼 늘어난다.\n\nIntent 분류는 맨 앞에서 한 번만 판단한다. \"주소 변경하고 싶어\"와 \"주소 어디서 바꿔요\"를 같은 갈래로 묶어 한 곳으로 보내면, 뒤에 있는 담당은 자기 일만 하면 된다."},"recap":"Intent 분류는 사용자 말을 미리 정해둔 갈래 중 하나로 대응시켜 어디로 보낼지 정하는 일이다. 확실한 정도를 함께 내놓기 때문에, 애매하면 되묻고 확실하면 바로 넘길 수 있다.","check":[{"q":"\"얼마나 남았어?\" 한 문장만으로 갈래를 정할 수 없는 이유는","at":"작동 원리"},{"q":"분류 점수가 기준에 못 미치는데 그대로 보내면 무슨 일이 생기나","at":"주의사항"},{"q":"갈래를 늘렸는데 오히려 분류가 부정확해졌다면 무엇을 의심해야 하나","at":"흔한 오해"}],"myths":[{"wrong":"의도를 알아냈으면 답도 나온 것이다","right":"어디로 보낼지가 정해졌을 뿐이다. 실제 답은 그 갈래를 맡은 쪽이 따로 만든다."},{"wrong":"갈래를 많이 만들수록 정확해진다","right":"갈래끼리 겹치기 시작하면 분류기가 헷갈린다. 서로 안 겹치게 적게 두는 편이 정확도가 높다."},{"wrong":"한 문장만 보면 된다","right":"앞선 대화를 안 보면 \"얼마나 남았어?\" 같은 말은 무엇을 묻는지 정할 수 없다."}],"cases":[{"label":"고객 문의 분류","note":"들어온 문의를 갈래로 나눠 담당 창구로 바로 보낸다."},{"label":"사내 챗봇","note":"신청 방법, 규정 확인, 급여 같은 갈래로 나눠 각각 다른 자료를 찾게 한다."},{"label":"애매한 질문 되묻기","note":"점수가 기준에 못 미치면 답을 지어내지 않고 선택지를 보여준다."}],"dia":{"shape":"흐름","title":"\"주소 변경하고 싶어\" 는 어디로 가나","rows":[{"who":"사용자","what":"자기 말로 요청을 적는다"},{"who":"분류기","what":"미리 정해둔 갈래에 대응시킨다"},{"who":"분류기","what":"갈래마다 얼마나 확실한지 점수를 낸다"},{"who":"판단","what":"점수가 기준을 넘으면 그 갈래로 정한다"},{"who":"담당","what":"정해진 쪽이 답을 만들어 돌려준다","back":true}],"sum":"무엇을 원하는지 먼저 정해야 어디로 보낼지가 나온다"}},"ai--llm":{"definition":"엄청난 양의 글로 학습해서, 주어진 문장 뒤에 무엇이 올 법한지를 안다. 그 예측을 한 단어씩 이어 붙인 것이 우리가 보는 답변이다.","analogy":"문장 완성 게임을 수천만 번 해본 사람. 사실을 외운 게 아니라 \"이런 말 뒤에는 보통 이런 말이 온다\"를 몸으로 익힌 상태다. 그래서 그럴듯한 말은 아는 것과 상관없이 잘 만든다.","example":"검색창에 몇 글자만 쳐도 뒷말이 미리 붙어 나오는 것을 겪어봤다면, 다음 말을 고른다는 게 어떤 일인지 이미 본 것이다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"핵심은 **문맥 창**이다. 모델이 한 번에 볼 수 있는 토큰 수가 정해져 있고, 그 밖의 내용은 존재하지 않는 것과 같다.\n\n같은 질문에 매번 다른 답이 나오는 것도 이 구조 때문이다. 가장 확률 높은 토큰만 고르면 답이 딱딱해져서, 보통은 상위 후보 중에서 무작위로 하나를 고른다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **문서 요약** — 긴 글을 넣고 짧게 다시 쓰게 한다. 원문이 문맥 창에 들어가야 한다.\n- **분류** — 문의 내용을 보고 어느 부서로 보낼지 정한다. 규칙으로 짜기 어려운 일이 잘 맞는다.\n- **코드 작성** — 자연어 설명을 코드로 옮긴다. 코드도 결국 토큰의 나열이라 같은 방식으로 예측된다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **LLM이 답을 검색해서 가져온다** — 검색하지 않는다. 학습한 통계로 그럴듯한 말을 만들어낼 뿐이라, 없는 논문 제목도 자신 있게 만들어낸다.\n- **모델이 대화를 기억한다** — 기억하지 않는다. 매번 대화 기록 전체를 다시 넣어주기 때문에 기억하는 것처럼 보인다. 창을 넘으면 앞이 사라진다.\n- **모델이 계산을 한다** — 계산하지 않고 계산 결과처럼 보이는 토큰을 예측한다. 자릿수가 큰 곱셈에서 틀리는 이유다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **틀린 답을 자신 있게 말한다.** 확률이 높은 문장은 맞는 문장과 다르다. 사실 확인이 필요한 곳에는 [[RAG]] 같은 근거 제공 장치를 붙인다.\n- **문맥 창은 비용이다.** 넣는 토큰만큼 돈과 시간이 든다. 대화 기록을 통째로 넣는 습관은 비싸진다."}],"figure":"```도해\n흐름: 질문을 넣으면 답이 어떻게 만들어지나\n사용자 :: \"한국의 수도는\" 이라고 입력한다\n토크나이저 :: 글자를 토큰이라는 조각으로 쪼갠다\n모델 :: 다음 토큰 후보마다 확률을 매긴다\n모델 :: \"서울\" 이 가장 높다. 하나 고른다\n< 사용자 :: 끝 신호가 나오면 이어 붙인 문장을 받는다\n@ 다시 예측으로 :: 고른 토큰을 뒤에 붙이고 한 조각 더\n= 문장 전체를 한 번에 만드는 게 아니라 한 조각씩 이어 붙인다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 규칙을 사람이 짜던 방식과 무엇이 다른가\n규칙 기반 |=| LLM\n새 표현 :: 규칙을 추가해야 || 대체로 처리된다\n분야 확장 :: 처음부터 다시 || 같은 모델로\n답의 근거 :: 규칙을 짚을 수 있다 || 짚기 어렵다\n= 사람이 규칙을 다 못 적는 문제를 풀었고, 대신 왜 그렇게 답했는지를 잃었다\n```\n\n말은 규칙으로 다 적을 수 없다. 예외가 너무 많고, 새 표현이 계속 생기고, 문맥에 따라 뜻이 달라진다. 규칙을 짜서 자연어를 다루려던 시도가 오래 막혀 있던 이유다.\n\nLLM은 규칙을 사람이 적는 대신 데이터에서 통계를 뽑는 방식으로 이 문제를 우회했다. 대신 답의 근거를 짚을 수 없게 됐고, 그래서 [[Hallucination]] 같은 문제가 따라온다."},"compose":{"label":"무엇으로 되어 있나","head":"🧱 구성","body":"```도해\n층: 답변 하나가 어떤 재료로 만들어지나\n시스템 지시 :: 어떤 역할로 답하라는 사전 지시\n대화 기록 :: 이번 대화에서 오간 말\n이번 질문 :: 방금 넣은 내용\n문맥 창 밖 :: 여기 있던 것은 모델에게 없는 것과 같다\n= 대화가 길어지면 앞부분이 창 밖으로 밀려나면서 \"기억\"이 사라진다\n```"},"recap":"LLM은 다음 토큰을 확률로 예측하는 모델이다. 규칙을 사람이 적지 않아도 되는 대신 근거를 짚을 수 없고, 그래서 확신에 찬 오답이 나온다.","check":[{"q":"대화가 길어지면 앞에서 한 말을 잊는 것처럼 보이는 이유는","at":"구성"},{"q":"없는 논문 제목을 만들어내는 일이 왜 버그가 아니라 구조상 당연한가","at":"흔한 오해"},{"q":"답이 길어질수록 다 나오는 데 시간이 더 걸리는 이유는","at":"그림"}],"myths":[{"wrong":"LLM이 답을 검색해서 가져온다","right":"검색하지 않는다. 학습한 통계로 그럴듯한 말을 만들어낼 뿐이라, 없는 논문 제목도 자신 있게 만들어낸다."},{"wrong":"모델이 대화를 기억한다","right":"기억하지 않는다. 매번 대화 기록 전체를 다시 넣어주기 때문에 기억하는 것처럼 보인다. 창을 넘으면 앞이 사라진다."},{"wrong":"모델이 계산을 한다","right":"계산하지 않고 계산 결과처럼 보이는 토큰을 예측한다. 자릿수가 큰 곱셈에서 틀리는 이유다."}],"cases":[{"label":"문서 요약","note":"긴 글을 넣고 짧게 다시 쓰게 한다. 원문이 문맥 창에 들어가야 한다."},{"label":"분류","note":"문의 내용을 보고 어느 부서로 보낼지 정한다. 규칙으로 짜기 어려운 일이 잘 맞는다."},{"label":"코드 작성","note":"자연어 설명을 코드로 옮긴다. 코드도 결국 토큰의 나열이라 같은 방식으로 예측된다."}],"dia":{"shape":"흐름","title":"질문을 넣으면 답이 어떻게 만들어지나","rows":[{"who":"사용자","what":"\"한국의 수도는\" 이라고 입력한다"},{"who":"토크나이저","what":"글자를 토큰이라는 조각으로 쪼갠다"},{"who":"모델","what":"다음 토큰 후보마다 확률을 매긴다"},{"who":"모델","what":"\"서울\" 이 가장 높다. 하나 고른다"},{"who":"사용자","what":"끝 신호가 나오면 이어 붙인 문장을 받는다","back":true}],"sum":"문장 전체를 한 번에 만드는 게 아니라 한 조각씩 이어 붙인다","loop":{"who":"다시 예측으로","what":"고른 토큰을 뒤에 붙이고 한 조각 더"}}},"ai--orchestrator":{"definition":"Agent 를 여러 개 만들어두는 것만으로는 쓸 수 없다. 들어온 질문이 어느 갈래인지 판단하고, 맡을 곳을 고르고, 여러 곳에서 온 답을 하나로 정리하는 자리가 따로 있어야 한다.","analogy":"병원 접수 창구. 증상을 듣고 어느 과로 보낼지 정하고, 여러 과를 봐야 하면 결과를 모아 한 장으로 준다.","example":"항공권 비교 사이트가 여러 항공사에 따로 물어보고 한 화면에 모아 보여주는 그 자리다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"Orchestrator 안은 네 자리로 나뉜다.\n\n| 자리 | 하는 일 |\n|---|---|\n| **의도 분류** | 질문이 어느 갈래인지 정한다 |\n| **라우터** | 갈래에 맞는 Agent 를 고른다 |\n| **Agent 풀** | 각자 한 영역만 맡은 실행기들 |\n| **응답 통합** | 여러 답을 하나의 문장으로 만든다 |\n\n앞에 선 것이 뒤를 정한다. **분류가 틀리면 뒤가 아무리 좋아도 엉뚱한 답이 나온다.**\n\n의도 분류는 대개 LLM 에게 갈래 목록을 주고 문장 전체를 보고 고르게 한다. 키워드만으로 나누면 같은 단어가 여러 갈래에 걸리는 순간 어긋난다.\n\n맡은 Agent 가 \"찾을 수 없다\"고 답했을 때 그대로 끝내지 않으려면 다음 후보 순서를 정해둬야 한다. 이것을 폴백이라고 하고, 응답이 충분한지 판단하는 기준을 같이 정해두어야 동작한다."},{"slot":"compare","label":"무엇과 비교되나","head":"📊 비교","body":"| | Router | Orchestrator |\n|---|---|---|\n| 하는 일 | 어디로 보낼지만 | 조율 전체 |\n| Agent 수 | 하나를 고른다 | 여럿을 부를 수 있다 |\n| 결과 통합 | 없다 | 있다 |\n| 실패 처리 | 거기서 끝 | 다음 후보로 넘김 |"},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **사내 문의 챗봇** — 규정 검색, 메뉴 안내, 급여 조회를 각각 맡은 Agent 를 두고 질문마다 하나만 부른다.\n- **복합 요청 분해** — 한 문장에 두 가지를 물으면 둘로 쪼개 각각 보내고 답을 번호로 묶어 돌려준다.\n- **폴백 사슬** — 맡은 Agent 가 못 찾으면 다음 후보에게 같은 질문을 넘겨 답이 나올 때까지 시도한다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **Orchestrator 는 라우터를 부르는 다른 말이다** — 라우터는 어디로 보낼지만 정한다. 여러 Agent 를 부르고 결과를 합치고 실패를 되받는 것까지가 조율이다.\n- **Agent 를 많이 붙일수록 답이 좋아진다** — 갈래가 늘수록 분류가 어려워진다. 잘못 고르면 좋은 Agent 가 있어도 엉뚱한 곳으로 간다.\n- **분류는 키워드만 잘 잡으면 된다** — 같은 단어가 여러 갈래에 걸친다. 그래서 대개 문장 전체를 보고 고르게 한다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **판단 못 한 경우를 정해둔다.** 갈래를 못 고른 질문을 아무 Agent 에게나 보내면 틀린 답이 그럴듯하게 나온다.\n- **분류 결과를 로그로 남긴다.** 답이 이상할 때 Agent 가 문제인지 분류가 문제인지 구분할 수 있어야 고칠 수 있다."}],"figure":"```도해\n흐름: 질문 하나가 들어오면 어느 Agent 가 답하게 되나\n사용자 :: 주소를 바꾸고 싶다고 쓴다\n분류 :: 이 질문이 어느 갈래인지 판단한다\n라우팅 :: 그 갈래를 맡은 Agent 를 고른다\nAgent :: 자기 영역에서 답을 찾아온다\n통합 :: 여러 답이면 하나로 정리한다\n< 사용자 :: 어느 Agent 가 답했는지는 모른 채 받는다\n= Agent 를 여러 개 두는 값은 어느 것을 부를지 정하는 자리에서 나온다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: Agent 를 여러 개 두기만 하면 어떻게 되나\n조율 없이 || Orchestrator 로\n질문 하나 :: 전부 응답한다 || 맡은 곳만 답\n답을 못 찾음 :: 거기서 끝난다 || 다음 곳에 물음\n요청이 둘 :: 사용자가 정리 || 하나로 묶어 줌\n= Agent 를 늘릴수록 어느 것을 부를지 정하는 일이 더 필요해진다\n```\n\n문서 검색, 메뉴 안내, 급여 조회를 각각 맡은 Agent 가 있다고 하자. \"주소 변경하고 싶어\"라는 한 문장에 셋이 전부 답하면 화면에는 서로 다른 세 개의 답이 뜬다. 사용자는 어느 것이 맞는지 알 수 없다.\n\nOrchestrator 는 그 앞에 판단을 하나 넣는다. 질문의 갈래를 정하고 맡을 곳 하나만 부른다. 실패하면 다음 후보에게 넘기고, 한 문장에 두 가지를 물었으면 둘로 쪼개 각각 보낸 뒤 결과를 합쳐 돌려준다."},"recap":"Orchestrator 는 요청을 보고 어느 Agent 에게 맡길지 정하고, 결과를 모아 한 답으로 만드는 층이다. 의도 분류, 라우팅, 실행, 통합으로 나뉘며 앞의 분류가 전체 품질을 좌우한다. 단순히 갈래를 나누기만 하는 라우터와는 다르다.","check":[{"q":"질문을 던졌는데 엉뚱한 Agent 가 답했다. 어느 자리를 먼저 의심하나","at":"작동 원리"},{"q":"Agent 한 곳이 못 찾았다고 답했을 때 그대로 끝나지 않게 하려면 무엇이 필요한가","at":"실제 사례"},{"q":"한 문장에 두 가지를 물으면 Orchestrator 는 무엇부터 해야 하나","at":"해결하는 문제"}],"myths":[{"wrong":"Orchestrator 는 라우터를 부르는 다른 말이다","right":"라우터는 어디로 보낼지만 정한다. 여러 Agent 를 부르고 결과를 합치고 실패를 되받는 것까지가 조율이다."},{"wrong":"Agent 를 많이 붙일수록 답이 좋아진다","right":"갈래가 늘수록 분류가 어려워진다. 잘못 고르면 좋은 Agent 가 있어도 엉뚱한 곳으로 간다."},{"wrong":"분류는 키워드만 잘 잡으면 된다","right":"같은 단어가 여러 갈래에 걸친다. 그래서 대개 문장 전체를 보고 고르게 한다."}],"cases":[{"label":"사내 문의 챗봇","note":"규정 검색, 메뉴 안내, 급여 조회를 각각 맡은 Agent 를 두고 질문마다 하나만 부른다."},{"label":"복합 요청 분해","note":"한 문장에 두 가지를 물으면 둘로 쪼개 각각 보내고 답을 번호로 묶어 돌려준다."},{"label":"폴백 사슬","note":"맡은 Agent 가 못 찾으면 다음 후보에게 같은 질문을 넘겨 답이 나올 때까지 시도한다."}],"dia":{"shape":"흐름","title":"질문 하나가 들어오면 어느 Agent 가 답하게 되나","rows":[{"who":"사용자","what":"주소를 바꾸고 싶다고 쓴다"},{"who":"분류","what":"이 질문이 어느 갈래인지 판단한다"},{"who":"라우팅","what":"그 갈래를 맡은 Agent 를 고른다"},{"who":"Agent","what":"자기 영역에서 답을 찾아온다"},{"who":"통합","what":"여러 답이면 하나로 정리한다"},{"who":"사용자","what":"어느 Agent 가 답했는지는 모른 채 받는다","back":true}],"sum":"Agent 를 여러 개 두는 값은 어느 것을 부를지 정하는 자리에서 나온다"}},"ai--prompt":{"definition":"같은 모델에 같은 질문을 해도 어떻게 적었느냐에 따라 답이 달라진다. 모델을 손대지 않고 답을 바꿀 수 있는 자리가 여기다.","analogy":"심부름 쪽지. \"우유 사와\"보다 \"1L 저지방으로, 없으면 일반으로\"가 원하던 걸 받을 확률이 높다.","example":"배달 앱 요청사항 칸에 문 앞에 놓아 달라고 적어 보낸 그 한 줄이 프롬프트다. 안 적으면 알아서 정한다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"모델은 받은 글을 토큰으로 쪼갠 뒤 앞의 토큰을 보고 다음 토큰을 하나씩 고른다. 지시를 이해하고 따르는 것이 아니라 그 지시 뒤에 올 법한 말을 이어 붙이는 쪽에 가깝다. 그래서 어떻게 적었는지가 답의 모양을 크게 흔든다.\n\n한 장의 프롬프트에는 네 가지가 들어간다. **시스템**은 대화 내내 지킬 역할과 말투를 깔아두는 자리, **지시**는 이번에 무엇을 해달라고 적는 자리다. **예시**는 답이 어떤 모양이어야 하는지 몇 개 보여주는 자리이고, **맥락**은 답에 쓸 문서나 데이터를 붙이는 자리다.\n\n```도해\n대조: 시스템 프롬프트와 나머지는 무엇이 다른가\n시스템 |=| 지시·예시·맥락\n적는 때 :: 대화 시작 전에 || 물을 때마다\n남는 기간 :: 대화 내내 || 이번 한 번\n담는 것 :: 역할과 말투 || 할 일과 자료\n= 한 번 깔아두고 계속 듣는 자리와 매번 새로 적는 자리가 나뉜다\n```\n\n예시를 하나도 주지 않고 시키는 것을 Zero-shot 이라 하고, 답의 모양을 두셋 보여준 뒤 시키는 것을 Few-shot 이라 한다. 답 대신 푸는 과정을 단계로 나눠 적으라고 시키는 것은 Chain-of-Thought 다. 사과 3개가 1,000원일 때 7개 값을 물으면서 단계를 나누라고 적으면, 한 개 값을 먼저 구하고 그다음에 곱하는 순서로 답이 나온다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **감정 분류** — 문장을 주고 긍정, 부정, 중립 중 하나로만 답하라고 적으면 라벨 하나만 돌아온다.\n- **고객 응대 챗봇** — 시스템 프롬프트에 존댓말을 쓰라고 깔아두면 대화가 이어지는 동안 말투가 유지된다.\n- **문서 기반 답변** — 문서를 붙이고 \"문서에 없으면 없다고 답하라\"고 못 박아 지어내는 답을 줄인다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **프롬프트는 질문이다** — 질문만이 아니다. 역할, 조건, 예시, 붙인 문서까지 모델에 들어가는 글 전부가 프롬프트다.\n- **프롬프트를 잘 쓰면 모델이 배운다** — 배우지 않는다. 그 요청 한 번에만 반영되고 다음 대화에는 남지 않는다. 모델 자체를 바꾸는 것은 Fine-tuning 이다.\n- **예시는 많이 넣을수록 좋다** — 예시도 프롬프트 안에 들어가고 넣을 수 있는 양에는 한계가 있다. 답의 모양을 보여줄 만큼만 넣는다."}],"figure":"```도해\n흐름: 프롬프트 한 장이 답이 되기까지 무엇을 거치나\n사람 :: 지시와 맥락을 한 덩어리 글로 적는다\n토큰화 :: 그 글이 토큰 조각으로 쪼개진다\nLLM :: 앞의 토큰을 보고 다음 토큰을 고른다\n< 사람 :: 멈출 자리까지 이어 붙인 답을 받는다\n@ 다시 고르기 :: 고른 토큰을 뒤에 붙이고 한 조각 더\n= 지시를 이해한 게 아니라 그 지시 뒤에 올 법한 말을 이어 붙인 것이다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 요약해달라고만 하면 무엇이 달라지나\n조건 없이 || 조건을 붙이면\n길이 :: 모델이 정한다 || 3줄로 못 박는다\n대상 :: 무엇을 요약할지 || 붙인 문서에서만\n말투 :: 그때그때 다름 || 정해둔 대로\n= 안 적어 보낸 자리는 모델이 알아서 메운다\n```\n\n\"요약해줘\"라고만 보내면 모델은 무엇을, 얼마나, 어떤 말투로 줄일지를 스스로 정한다. 정할 근거가 없으니 매번 다른 답이 나온다. \"이거 언제야?\"처럼 가리키는 말이 들어가면 무엇을 가리키는지조차 몰라 되묻는 답이 돌아온다.\n\n프롬프트에 조건을 적으면 그만큼이 정해진다. \"다음 문서를 3줄로 요약하세요\"라고 쓰고 문서를 붙이면 길이와 대상이 같이 박힌다. 안 적은 자리는 여전히 모델이 메운다는 점만 기억하면 된다."},"recap":"Prompt는 LLM 에게 들어가는 글 전부다. 모델을 손대지 않고 답을 바꿀 수 있는 유일한 자리이고, 적어 보내지 않은 조건은 모델이 알아서 메운다. 역할과 지시와 예시와 맥락을 어디까지 적을지 고르는 일이 프롬프트를 쓰는 일이다.","check":[{"q":"\"요약해줘\" 한 마디만 보냈을 때 길이와 말투는 누가 정하나","at":"해결하는 문제"},{"q":"예시 세 개를 넣어 답이 좋아졌다면 모델이 그 예시를 배운 것인가","at":"흔한 오해"},{"q":"시스템 프롬프트에 적은 말투가 다음 질문에도 남아 있는 이유는","at":"작동 원리"}],"myths":[{"wrong":"프롬프트는 질문이다","right":"질문만이 아니다. 역할, 조건, 예시, 붙인 문서까지 모델에 들어가는 글 전부가 프롬프트다."},{"wrong":"프롬프트를 잘 쓰면 모델이 배운다","right":"배우지 않는다. 그 요청 한 번에만 반영되고 다음 대화에는 남지 않는다. 모델 자체를 바꾸는 것은 Fine-tuning 이다."},{"wrong":"예시는 많이 넣을수록 좋다","right":"예시도 프롬프트 안에 들어가고 넣을 수 있는 양에는 한계가 있다. 답의 모양을 보여줄 만큼만 넣는다."}],"cases":[{"label":"감정 분류","note":"문장을 주고 긍정, 부정, 중립 중 하나로만 답하라고 적으면 라벨 하나만 돌아온다."},{"label":"고객 응대 챗봇","note":"시스템 프롬프트에 존댓말을 쓰라고 깔아두면 대화가 이어지는 동안 말투가 유지된다."},{"label":"문서 기반 답변","note":"문서를 붙이고 \"문서에 없으면 없다고 답하라\"고 못 박아 지어내는 답을 줄인다."}],"dia":{"shape":"흐름","title":"프롬프트 한 장이 답이 되기까지 무엇을 거치나","rows":[{"who":"사람","what":"지시와 맥락을 한 덩어리 글로 적는다"},{"who":"토큰화","what":"그 글이 토큰 조각으로 쪼개진다"},{"who":"LLM","what":"앞의 토큰을 보고 다음 토큰을 고른다"},{"who":"사람","what":"멈출 자리까지 이어 붙인 답을 받는다","back":true}],"sum":"지시를 이해한 게 아니라 그 지시 뒤에 올 법한 말을 이어 붙인 것이다","loop":{"who":"다시 고르기","what":"고른 토큰을 뒤에 붙이고 한 조각 더"}}},"ai--prompt-engineering":{"definition":"같은 모델도 무엇을 어떻게 물었느냐에 따라 다른 답을 내놓는다. 모델을 고치는 대신 입력을 고쳐서 답의 범위를 좁히는 것이 이 일이다.","analogy":"택배 기사에게 주소를 적어주는 것. \"우리 집\"이라고 쓰면 못 찾고, 동과 호수까지 쓰면 한 번에 온다.","example":"검색이 엉뚱하게 나올 때 낱말을 바꿔 다시 쳐서 원하던 결과를 얻어본 적이 있다. 그 고쳐 치는 일이 여기서 하는 일이다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"```도해\n층: 프롬프트에 무엇부터 얹나\n할 일 :: 무엇을 만들지 한 문장으로 적는다\n조건 :: 형식, 길이, 쓰지 말 것을 적는다\n예시 :: 원하는 답을 한두 벌 보여준다\n생각 순서 :: \"단계별로 생각해보자\" 처럼 절차를 준다\n= 위쪽만으로 되면 아래를 붙일 이유가 없다. 안 될 때 하나씩 얹는다\n```\n\n예시 없이 지시만 주는 것을 Zero-shot이라고 한다. 답의 형식이 흔들리면 예시를 한두 개 붙이는데, 이게 Few-shot이다. \"긍정/부정\"처럼 라벨을 정해 보여주면 그 표기를 따라온다.\n\n계산이나 추론이 섞이면 \"단계별로 생각해보자\"를 덧붙인다. 피자 세 판을 여덟 명이 나누는 문제에서 답만 던지는 대신 전체 조각을 먼저 세고 나누는 식으로 과정을 적게 하는 것을 Chain-of-Thought라고 한다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **분류 작업** — 예시 두 개를 붙여주면 라벨 표기가 예시와 같은 모양으로 나온다.\n- **계산 문제** — 과정을 적게 하면 답만 던질 때보다 덜 틀리고, 틀렸을 때 어디서 어긋났는지 보인다.\n- **코드 요청** — 쓸 라이브러리, 입력과 출력, 예외 처리 여부를 적어주면 받아서 고칠 일이 줄어든다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **프롬프트는 길게 쓸수록 좋다** — 길이가 아니라 무엇이 적혀 있느냐다. 상관없는 말을 늘리면 정작 지켜야 할 조건이 그 안에 묻힌다.\n- **성능을 올려주는 마법의 문장이 있다** — \"당신은 전문가입니다\" 한 줄이 없던 지식을 만들어주지는 않는다. 역할을 주는 것은 말투와 관점의 범위를 좁히는 일이다.\n- **잘 물으면 모르는 것도 답해준다** — 프롬프트는 무엇을 어떤 모양으로 답할지를 정할 뿐이다. 모델이 갖고 있지 않은 사실이 필요하면 그 자료를 프롬프트에 같이 넣어야 한다."}],"figure":"```도해\n흐름: 프롬프트를 고쳐 쓰면 답이 어떻게 달라지나\n막연한 요청 :: \"코드 짜줘\". 언어도 조건도 없다\n할 일 적기 :: 무엇을 만들지 한 문장으로 못 박는다\n조건 적기 :: 쓸 라이브러리와 입력, 출력을 적는다\n예시 넣기 :: 원하는 답의 모양을 한 벌 보여준다\n< 모델 :: 좁아진 범위 안에서 골라 답을 돌려준다\n= 모델은 마음을 읽지 않는다. 안 적은 것은 알아서 정한다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 요청을 대충 적으면 무엇이 달라지나\n막연한 요청 || 조건을 적은 요청\n결과 :: 매번 다르다 || 모양이 고정된다\n다시 시키기 :: 계속 고쳐 말한다 || 한 번에 끝난다\n쓸 수 있나 :: 손보고 써야 한다 || 그대로 붙인다\n= 안 적은 조건은 모델이 대신 정해버린다\n```\n\n\"코드 작성해줘\"라고만 하면 언어도, 쓸 라이브러리도, 예외 처리 여부도 모델이 정한다. 그때그때 다른 선택을 하니 같은 요청에 다른 답이 오고, 받을 때마다 고쳐 써야 한다.\n\n프롬프트에 그 선택지들을 미리 적어두면 모델이 정할 몫이 줄어든다. 답이 매번 비슷한 모양으로 나오고, 그래야 다음 단계에 그대로 넘길 수 있다."},"recap":"Prompt Engineering은 모델이 알아서 정하던 몫을 줄여 답을 예측 가능하게 만드는 일이다. 지시, 조건, 예시, 생각 순서를 필요한 만큼만 얹고, 안 될 때 하나씩 더한다.","check":[{"q":"\"코드 짜줘\"라고만 했을 때 같은 요청에 매번 다른 답이 오는 이유는","at":"해결하는 문제"},{"q":"예시를 한두 개 붙였을 때 답의 무엇이 고정되나","at":"실제 사례"},{"q":"계산 문제에서 답만 던지고 틀릴 때 프롬프트에 무엇을 덧붙이나","at":"작동 원리"}],"myths":[{"wrong":"프롬프트는 길게 쓸수록 좋다","right":"길이가 아니라 무엇이 적혀 있느냐다. 상관없는 말을 늘리면 정작 지켜야 할 조건이 그 안에 묻힌다."},{"wrong":"성능을 올려주는 마법의 문장이 있다","right":"\"당신은 전문가입니다\" 한 줄이 없던 지식을 만들어주지는 않는다. 역할을 주는 것은 말투와 관점의 범위를 좁히는 일이다."},{"wrong":"잘 물으면 모르는 것도 답해준다","right":"프롬프트는 무엇을 어떤 모양으로 답할지를 정할 뿐이다. 모델이 갖고 있지 않은 사실이 필요하면 그 자료를 프롬프트에 같이 넣어야 한다."}],"cases":[{"label":"분류 작업","note":"예시 두 개를 붙여주면 라벨 표기가 예시와 같은 모양으로 나온다."},{"label":"계산 문제","note":"과정을 적게 하면 답만 던질 때보다 덜 틀리고, 틀렸을 때 어디서 어긋났는지 보인다."},{"label":"코드 요청","note":"쓸 라이브러리, 입력과 출력, 예외 처리 여부를 적어주면 받아서 고칠 일이 줄어든다."}],"dia":{"shape":"흐름","title":"프롬프트를 고쳐 쓰면 답이 어떻게 달라지나","rows":[{"who":"막연한 요청","what":"\"코드 짜줘\". 언어도 조건도 없다"},{"who":"할 일 적기","what":"무엇을 만들지 한 문장으로 못 박는다"},{"who":"조건 적기","what":"쓸 라이브러리와 입력, 출력을 적는다"},{"who":"예시 넣기","what":"원하는 답의 모양을 한 벌 보여준다"},{"who":"모델","what":"좁아진 범위 안에서 골라 답을 돌려준다","back":true}],"sum":"모델은 마음을 읽지 않는다. 안 적은 것은 알아서 정한다"}},"ai--rag":{"definition":"모델은 학습한 것만 안다. 우리 회사 규정이나 어제 올라온 문서는 모른다. 질문이 오면 먼저 그 문서를 찾아서 질문과 함께 넣어주면, 모델은 그 내용을 보고 답한다.","analogy":"개방형 시험. 외운 것만으로 답하게 하면 틀리거나 지어내지만, 교재를 펴놓고 답하게 하면 근거를 짚어 답한다.","example":"검색 결과 맨 위에 요약이 뜨면서 그 아래 출처 링크가 같이 달려 나오는 화면이 이 모양이다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"준비 단계와 응답 단계가 나뉜다.\n\n```도해\n흐름: 문서 한 장이 답의 근거가 되기까지 무엇을 거치나\n쪼개기 :: 긴 문서를 문단 단위로 자른다\n임베딩 :: 조각마다 뜻을 벡터로 만든다\n저장 :: 벡터 DB 에 넣어둔다\n검색 :: 질문이 오면 가까운 조각을 꺼낸다\n= 앞의 셋은 미리 해두고, 마지막 하나만 질문할 때 한다\n```\n\n쪼개는 크기가 품질을 크게 좌우한다. 너무 크면 관계없는 내용이 섞여 들어오고, 너무 작으면 문맥이 끊겨서 무슨 말인지 알 수 없게 된다."},{"slot":"compare","label":"무엇과 비교되나","head":"📊 비교: 일반 LLM vs RAG vs Fine-tuning","body":"| | 일반 LLM | RAG | Fine-tuning |\n|---|---|---|---|\n| 지식 출처 | 학습 데이터 | 바깥 문서 | 재학습 데이터 |\n| 최신 정보 | 안 된다 | 문서만 고치면 된다 | 다시 학습해야 한다 |\n| 출처 표시 | 못 한다 | 조각까지 댄다 | 못 한다 |\n| 바꾸는 비용 | 바꿀 수 없다 | 낮다 | 높다 |"},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **사내 문서 검색** — 규정, 매뉴얼, 회의록을 넣어두고 자연어로 묻는다.\n- **고객 문의 응대** — 제품 문서를 근거로 답하고 링크를 함께 준다.\n- **코드베이스 질문** — 저장소를 쪼개 넣어두면 \"이 함수 어디서 쓰나\"를 물을 수 있다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **RAG를 붙이면 환각이 사라진다** — 줄어들 뿐이다. 검색이 엉뚱한 문서를 가져오면 그 엉뚱한 문서를 근거로 그럴듯하게 지어낸다.\n- **문서를 다 넣으면 된다** — 문맥 창에 한계가 있어서 다 넣을 수 없다. 무엇을 골라 넣느냐가 이 방식의 전부다.\n- **검색이 키워드로 이뤄진다** — 뜻으로 찾는다. \"연차\"라고 물어도 \"휴가 규정\" 문서가 나오는 것이 이 방식의 장점이자, 엉뚱한 문서를 가져오는 이유다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **검색 품질이 답의 상한이다.** 모델을 바꾸기 전에 무엇을 가져왔는지부터 본다. 나쁜 답의 대부분은 나쁜 검색에서 나온다.\n- **권한을 검색 단계에서 거른다.** 문서를 다 넣어두면 권한 없는 사용자에게도 내용이 나갈 수 있다."}],"figure":"```도해\n흐름: 사내 규정을 물으면 무슨 일이 일어나나\n사용자 :: \"연차는 며칠인가요\" 라고 묻는다\n검색기 :: 질문을 벡터(뜻을 담은 숫자 목록)로 바꾼다\n벡터 DB :: 뜻이 가까운 문서 조각 세 개를 꺼낸다\n조립 :: 찾은 조각 + 원래 질문을 하나로 묶는다\n모델 :: 그 묶음만 보고 답을 만든다\n< 사용자 :: 출처가 붙은 답을 받는다\n= 모델을 다시 학습시키지 않고도 새 지식을 쓰게 만드는 방법이다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 사내 문서를 모델에 물으려면 어떻게 하나\nRAG 없이 || RAG 로\n새 문서 반영 :: 재학습 필요 || 넣으면 바로\n출처 :: 알 수 없다 || 문서를 짚어준다\n비용 :: 학습 비용이 크다 || 검색 비용만\n= 지식을 모델 안에 넣지 않고 밖에 두는 것이 이 방식의 요점이다\n```\n\n모델을 우리 데이터로 다시 학습시키는 방법도 있지만 비싸고 오래 걸린다. 문서가 하나 바뀔 때마다 다시 학습할 수는 없다.\n\nRAG는 지식을 모델 밖에 둔다. 문서가 바뀌면 저장소만 갱신하면 되고, 답에 어느 문서를 봤는지 붙일 수 있어서 사람이 확인할 수 있다. [[Hallucination]]이 줄어드는 것도 지어낼 필요가 없어지기 때문이다."},"recap":"RAG는 답하기 전에 관련 문서를 찾아 함께 넣어주는 방식이다. 지식을 모델 밖에 두어 갱신과 출처 표시가 쉬워지고, 대신 검색 품질이 답의 품질을 정한다.","check":[{"q":"답이 엉뚱하다면 모델과 검색 중 어디를 먼저 봐야 하나","at":"주의사항"},{"q":"문서를 통째로 넣지 못하는 이유는","at":"흔한 오해"},{"q":"문서 조각을 너무 작게 자르면 무엇이 문제가 되나","at":"작동 원리"}],"myths":[{"wrong":"RAG를 붙이면 환각이 사라진다","right":"줄어들 뿐이다. 검색이 엉뚱한 문서를 가져오면 그 엉뚱한 문서를 근거로 그럴듯하게 지어낸다."},{"wrong":"문서를 다 넣으면 된다","right":"문맥 창에 한계가 있어서 다 넣을 수 없다. 무엇을 골라 넣느냐가 이 방식의 전부다."},{"wrong":"검색이 키워드로 이뤄진다","right":"뜻으로 찾는다. \"연차\"라고 물어도 \"휴가 규정\" 문서가 나오는 것이 이 방식의 장점이자, 엉뚱한 문서를 가져오는 이유다."}],"cases":[{"label":"사내 문서 검색","note":"규정, 매뉴얼, 회의록을 넣어두고 자연어로 묻는다."},{"label":"고객 문의 응대","note":"제품 문서를 근거로 답하고 링크를 함께 준다."},{"label":"코드베이스 질문","note":"저장소를 쪼개 넣어두면 \"이 함수 어디서 쓰나\"를 물을 수 있다."}],"dia":{"shape":"흐름","title":"사내 규정을 물으면 무슨 일이 일어나나","rows":[{"who":"사용자","what":"\"연차는 며칠인가요\" 라고 묻는다"},{"who":"검색기","what":"질문을 벡터(뜻을 담은 숫자 목록)로 바꾼다"},{"who":"벡터 DB","what":"뜻이 가까운 문서 조각 세 개를 꺼낸다"},{"who":"조립","what":"찾은 조각 + 원래 질문을 하나로 묶는다"},{"who":"모델","what":"그 묶음만 보고 답을 만든다"},{"who":"사용자","what":"출처가 붙은 답을 받는다","back":true}],"sum":"모델을 다시 학습시키지 않고도 새 지식을 쓰게 만드는 방법이다"}},"ai--react":{"definition":"한 번에 답을 내놓는 대신, 무엇이 필요한지 생각하고, 도구를 하나 쓰고, 그 결과를 보고 다시 생각한다. 이름은 Reasoning과 Acting을 붙인 것이다.","analogy":"요리하면서 냉장고를 열어보는 것. 재료를 다 외운 채로 순서를 짜지 않고, 한 번 열어보고 있는 것에 맞춰 다음 손을 정한다.","example":"내비게이션이 가다가 막힌 길을 확인하고 경로를 새로 잡아 주는 그 되잡음이 한 바퀴다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"한 바퀴는 세 마디로 되어 있다.\n\n| 마디 | 하는 일 |\n|---|---|\n| **Thought** | 지금 무엇이 필요한지 말로 적는다 |\n| **Action** | 도구 하나를 고르고 부른다 |\n| **Observation** | 도구가 돌려준 결과를 읽는다 |\n\n이 세 마디가 목표에 닿을 때까지 반복된다. 필요한 게 다 모였다고 판단하면 도구를 부르는 대신 답을 내놓고 끝낸다.\n\n생각을 겉으로 적게 한다는 점이 이 방식의 특징이다. 판단을 글로 남기므로 나중에 기록을 열어보면 어느 판단에서 틀어졌는지 보이고, 도구를 잘못 고른 것인지 결과를 잘못 읽은 것인지도 구분할 수 있다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **사내 챗봇** — 남은 휴가 일수를 물으면 인사 시스템을 조회하고 그 값으로 답한다. 모델이 기억하던 값을 쓰지 않는다.\n- **자료 검색** — 한 번 검색해서 부족하면 검색어를 바꿔 다시 찾는다. 관찰한 결과가 다음 검색어를 정한다.\n- **여러 단계 계산** — 환율을 받아온 다음 그 값으로 금액을 계산한다. 앞 단계 결과가 없으면 뒤 단계를 시작하지 않는다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **ReAct는 모델 이름이다** — 모델이 아니라 모델을 부리는 방식이다. 같은 모델을 한 번에 답하게 할 수도 있고 ReAct로 돌게 할 수도 있다.\n- **ReAct를 쓰면 지어내기가 없어진다** — 줄어들 뿐이다. 도구를 안 부르고 넘어가거나 결과를 잘못 읽으면 틀린 답이 그대로 나간다.\n- **바퀴를 많이 돌수록 답이 좋아진다** — 한 바퀴마다 모델 호출 비용이 붙고, 방향을 잘못 잡으면 잘못된 채로 계속 돈다. 몇 바퀴까지 돌지 정해두는 편이 낫다."}],"figure":"```도해\n흐름: \"내일 서울 날씨 어때?\" 를 받으면 어떻게 답하나\n사용자 :: 내일 서울 날씨를 묻는다\n생각 :: 실시간 정보가 필요하다고 적는다\n행동 :: 날씨 API 를 부른다\n관찰 :: \"맑음, 15도\" 라는 결과를 읽는다\n@ 다시 생각으로 :: 다 모였으면 답하고, 아니면 한 바퀴 더\n= 생각과 행동과 관찰이 한 바퀴고, 필요한 만큼 돈다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 실시간 정보를 물으면 무엇이 달라지나\n그냥 LLM || ReAct 로\n모르는 값 :: 못 한다고 답 || 도구로 찾는다\n여러 단계 :: 한 번에 추측 || 나눠서 진행\n중간 오류 :: 그대로 나감 || 보고 고친다\n= 모르는 것을 지어내는 대신 알아보러 가게 만드는 구조다\n```\n\n학습해둔 것만으로 답하는 모델은 지금 이 순간의 값을 모른다. 내일 날씨나 방금 바뀐 재고 수량을 물으면 확인할 수 없다고 답하거나, 더 나쁘면 그럴듯한 숫자를 지어낸다.\n\nReAct는 답하기 전에 한 단계를 끼워 넣는다. 무엇이 필요한지 먼저 말로 적게 하고, 그다음에 도구를 부르게 한다. 도구가 돌려준 값을 보고 다시 판단하므로 한 번에 맞힐 필요가 없고, 중간에 어긋난 것을 알아채면 방향을 바꿀 수 있다."},"recap":"ReAct는 생각, 행동, 관찰을 한 바퀴로 삼아 반복하는 에이전트 방식이다. 모르는 값을 지어내는 대신 도구로 알아보게 만들고, 판단을 글로 남기게 해서 어디서 어긋났는지 되짚을 수 있게 한다.","check":[{"q":"그냥 LLM에게 내일 날씨를 물으면 왜 답을 못 하나","at":"해결하는 문제"},{"q":"검색 한 번으로 부족했을 때 다음 검색어는 무엇을 근거로 정해지나","at":"실제 사례"},{"q":"바퀴 수에 한도를 두지 않으면 어떤 일이 생기나","at":"흔한 오해"}],"myths":[{"wrong":"ReAct는 모델 이름이다","right":"모델이 아니라 모델을 부리는 방식이다. 같은 모델을 한 번에 답하게 할 수도 있고 ReAct로 돌게 할 수도 있다."},{"wrong":"ReAct를 쓰면 지어내기가 없어진다","right":"줄어들 뿐이다. 도구를 안 부르고 넘어가거나 결과를 잘못 읽으면 틀린 답이 그대로 나간다."},{"wrong":"바퀴를 많이 돌수록 답이 좋아진다","right":"한 바퀴마다 모델 호출 비용이 붙고, 방향을 잘못 잡으면 잘못된 채로 계속 돈다. 몇 바퀴까지 돌지 정해두는 편이 낫다."}],"cases":[{"label":"사내 챗봇","note":"남은 휴가 일수를 물으면 인사 시스템을 조회하고 그 값으로 답한다. 모델이 기억하던 값을 쓰지 않는다."},{"label":"자료 검색","note":"한 번 검색해서 부족하면 검색어를 바꿔 다시 찾는다. 관찰한 결과가 다음 검색어를 정한다."},{"label":"여러 단계 계산","note":"환율을 받아온 다음 그 값으로 금액을 계산한다. 앞 단계 결과가 없으면 뒤 단계를 시작하지 않는다."}],"dia":{"shape":"흐름","title":"\"내일 서울 날씨 어때?\" 를 받으면 어떻게 답하나","rows":[{"who":"사용자","what":"내일 서울 날씨를 묻는다"},{"who":"생각","what":"실시간 정보가 필요하다고 적는다"},{"who":"행동","what":"날씨 API 를 부른다"},{"who":"관찰","what":"\"맑음, 15도\" 라는 결과를 읽는다"}],"sum":"생각과 행동과 관찰이 한 바퀴고, 필요한 만큼 돈다","loop":{"who":"다시 생각으로","what":"다 모였으면 답하고, 아니면 한 바퀴 더"}}},"ai--reranking":{"definition":"RAG에서 문서를 찾을 때 한 번에 정확히 고르려 하지 않는다. 빠른 검색으로 후보를 넉넉히 뽑아둔 다음, 그 안에서만 정밀한 모델로 다시 채점해 위에서 몇 건만 남긴다.","analogy":"서류 심사와 면접. 서류로는 수백 명을 빠르게 걸러 열 명을 남기고, 면접은 그 열 명만 한 명씩 오래 본다. 면접을 수백 명에게 할 수는 없다.","example":"중고 거래 앱에서 검색하면 제목만 닮은 매물이 잔뜩 뜨고 진짜 찾던 것은 아래에 묻혀 있다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"두 단계가 점수를 매기는 방식이 다르다. 벡터 검색은 문서를 미리 숫자 벡터로 바꿔 저장해두고, 질문도 벡터로 바꿔 둘 사이의 거리만 잰다. 문서 쪽 계산이 이미 끝나 있어서 수만 건을 순식간에 훑을 수 있지만, 질문과 문서를 따로 계산했기 때문에 둘 사이의 관계는 대략적으로만 반영된다.\n\n리랭커는 질문과 문서를 한 쌍으로 묶어 모델에 함께 넣고 점수를 낸다. 이런 방식을 Cross-Encoder라고 한다. 질문이 정해진 다음에야 계산할 수 있으니 미리 색인해둘 수 없고, 그래서 후보 하나하나에 시간이 든다. 1차가 0.1초라면 2차는 0.5초 정도가 붙는다.\n\n정리하면 1차는 후보를 놓치지 않기 위한 단계, 2차는 그 후보들 사이의 순서를 바로잡기 위한 단계다."},{"slot":"compare","label":"무엇과 비교되나","head":"📊 비교: 두 단계가 하는 일","body":"| | 벡터 검색 | 리랭킹 |\n|---|---|---|\n| 보는 대상 | 색인된 문서 전체 | 1차가 뽑은 몇 건 |\n| 계산 | 미리 만든 벡터끼리 거리 | 질문과 문서를 붙여 채점 |\n| 걸리는 시간 | 0.1초 | 0.5초 |\n| 잘하는 일 | 놓치지 않고 넓게 뽑기 | 그 안에서 정확히 고르기 |"},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **사내 규정 검색** — 비슷한 문장이 여러 규정에 흩어져 있을 때 질문에 실제로 답하는 조항을 위로 올린다.\n- **컨텍스트 아끼기** — 10건을 다 넣는 대신 3건만 넣어 토큰을 줄이고 엉뚱한 문서에 끌려가는 것을 막는다.\n- **제목만 닮은 문서가 많은 문서고** — 겉모습이 비슷해 위에 몰린 문서들을 내용 기준으로 다시 세운다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **리랭킹은 검색을 한 번 더 하는 것이다** — 다시 찾아오지 않는다. 1차가 뽑아온 목록 안에서 순서만 바꾸므로 1차에서 빠진 문서는 리랭킹으로도 올라오지 않는다.\n- **벡터 검색 점수가 높으면 답에 가깝다** — 그 점수는 질문과 문서가 얼마나 닮았는지에 가깝다. 질문과 닮은 문서와 질문에 답하는 문서는 다를 수 있고, 그 차이를 리랭커가 다시 본다.\n- **리랭커도 결국 벡터끼리 비교하는 것 아닌가** — 질문과 문서를 한 쌍으로 묶어 모델에 같이 넣고 점수를 낸다. 미리 계산해둘 수 없어 느린 대신 둘 사이의 관계를 직접 본다."}],"figure":"```도해\n흐름: 질문 하나가 들어오면 문서는 어떤 순서로 걸러지나\n질문 :: \"육아휴직 기간은?\" 이 들어온다\n벡터 검색 :: 수만 건에서 비슷해 보이는 10건을 0.1초에 뽑는다\n리랭커 :: 그 10건을 질문과 짝지어 하나씩 다시 채점한다\n순위 :: 새 점수 순으로 세워 위에서 3건만 남긴다\nLLM :: 남은 3건만 읽고 답을 만든다\n= 넓게 훑는 일과 꼼꼼히 보는 일을 다른 단계에 나눠 맡긴다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 벡터 검색 점수만 보고 위에서 자르면 어떻게 되나\n리랭킹 없이 || 리랭킹으로\n점수 차이 :: 0.85 대 0.83 || 0.95 대 0.70\n진짜 답 :: 2위에 묻힌다 || 1위로 올라온다\n읽는 문서 :: 애매한 10건 || 확실한 3건\n= 넓게 뽑는 일과 정확히 고르는 일은 잘하는 모델이 다르다\n```\n\n벡터 검색은 빠르지만 점수 차이가 촘촘하다. 1위가 0.85이고 2위가 0.83이면 이 순서를 믿을 근거가 별로 없다. 실제로는 2위 문서가 질문에 정확히 답하고 있는데도 1위 아래에 묻히는 일이 생긴다.\n\n문서를 많이 넘겨서 해결할 수도 없다. 10건을 그대로 LLM에 넣으면 토큰을 더 쓰는 데다 관련 없는 문서가 답을 흐린다. 리랭킹은 후보를 넉넉히 뽑는 것과 정확히 고르는 것을 두 단계로 나눠서, 1차에서는 놓치지 않는 데만 집중하고 고르는 일은 2차에 맡긴다."},"recap":"Reranking은 빠른 검색이 뽑아온 후보를 정밀한 모델로 다시 채점해 순서를 바로잡는 단계다. 1차는 놓치지 않는 데 집중하고 2차는 그 안에서 고르는 데 집중하도록 역할을 나눈 것이다. 대신 1차에서 빠진 문서는 되살릴 수 없으므로 후보를 넉넉히 뽑아두는 쪽이 중요해진다.","check":[{"q":"1차 검색에서 아예 뽑히지 않은 문서를 리랭킹이 살릴 수 없는 이유는","at":"흔한 오해"},{"q":"벡터 검색 점수만 보고 위에서 3건을 자르면 무엇을 놓치게 되나","at":"해결하는 문제"},{"q":"리랭커가 벡터 검색보다 느린 이유는","at":"작동 원리"}],"myths":[{"wrong":"리랭킹은 검색을 한 번 더 하는 것이다","right":"다시 찾아오지 않는다. 1차가 뽑아온 목록 안에서 순서만 바꾸므로 1차에서 빠진 문서는 리랭킹으로도 올라오지 않는다."},{"wrong":"벡터 검색 점수가 높으면 답에 가깝다","right":"그 점수는 질문과 문서가 얼마나 닮았는지에 가깝다. 질문과 닮은 문서와 질문에 답하는 문서는 다를 수 있고, 그 차이를 리랭커가 다시 본다."},{"wrong":"리랭커도 결국 벡터끼리 비교하는 것 아닌가","right":"질문과 문서를 한 쌍으로 묶어 모델에 같이 넣고 점수를 낸다. 미리 계산해둘 수 없어 느린 대신 둘 사이의 관계를 직접 본다."}],"cases":[{"label":"사내 규정 검색","note":"비슷한 문장이 여러 규정에 흩어져 있을 때 질문에 실제로 답하는 조항을 위로 올린다."},{"label":"컨텍스트 아끼기","note":"10건을 다 넣는 대신 3건만 넣어 토큰을 줄이고 엉뚱한 문서에 끌려가는 것을 막는다."},{"label":"제목만 닮은 문서가 많은 문서고","note":"겉모습이 비슷해 위에 몰린 문서들을 내용 기준으로 다시 세운다."}],"dia":{"shape":"흐름","title":"질문 하나가 들어오면 문서는 어떤 순서로 걸러지나","rows":[{"who":"질문","what":"\"육아휴직 기간은?\" 이 들어온다"},{"who":"벡터 검색","what":"수만 건에서 비슷해 보이는 10건을 0.1초에 뽑는다"},{"who":"리랭커","what":"그 10건을 질문과 짝지어 하나씩 다시 채점한다"},{"who":"순위","what":"새 점수 순으로 세워 위에서 3건만 남긴다"},{"who":"LLM","what":"남은 3건만 읽고 답을 만든다"}],"sum":"넓게 훑는 일과 꼼꼼히 보는 일을 다른 단계에 나눠 맡긴다"}},"ai--routing":{"definition":"같은 시스템 안에 메뉴 안내, 규정 검색, 급여 조회처럼 서로 다른 처리자가 여럿 있으면 누가 맡을지부터 정해야 한다. 라우팅은 그 판단만 맡고 답은 만들지 않는다.","analogy":"회사 대표번호의 자동 교환. 용건을 듣고 담당 부서로 이어주기만 하고, 상담은 그쪽에서 한다.","example":"대표 메일 주소로 문의를 보냈는데 며칠 뒤 담당자 이름으로 답이 오는 것을 본 적이 있다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"```도해\n층: 어느 처리자인지 무엇으로 가리나\n규칙 :: 정해둔 낱말이 있으면 바로 그쪽으로\n분류 모델 :: 문장의 의도를 이름 하나로 가른다\n의미 유사도 :: 처리자 설명과 얼마나 가까운지 잰다\n모름 :: 어느 쪽도 확실하지 않을 때 가는 자리\n= 위쪽일수록 싸고 확실하고, 아래로 갈수록 넓게 잡는다\n```\n\n분류 결과에는 신뢰도가 따라온다. 기준을 정해두고 그 아래면 어느 처리자에게도 넘기지 않는다. 애매한 것을 억지로 보내는 것보다 되묻는 편이 낫기 때문이다.\n\n처리자를 고른 다음에도 바로 넘기지 않을 수 있다. 그 사용자에게 조회 권한이 있는지, 지금이 처리 가능한 시간인지, 입력에 개인정보가 섞여 있지는 않은지를 라우터 자리에서 먼저 본다."},{"slot":"compare","label":"무엇과 비교되나","head":"📊 비교","body":"| | Routing | Orchestration |\n|---|---|---|\n| 하는 일 | 하나를 고른다 | 여럿을 부린다 |\n| 결과 합치기 | 없다 | 있다 |\n| 요청 모양 | 한 가지 용건 | 여러 용건이 섞임 |\n| 복잡도 | 규칙표 하나 | 순서와 예외까지 |"},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **권한 확인** — 급여 쪽으로 갈 요청이라도 조회 권한이 없으면 처리자에 닿기 전에 막고 안내로 돌린다.\n- **모름 처리** — 분류 신뢰도가 기준 아래면 아무에게도 넘기지 않고 무엇을 원하는지 되묻는다.\n- **처리자 추가** — 새 처리자를 붙일 때 규칙표에 한 줄만 더하고 기존 코드는 그대로 둔다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **라우터가 답을 만든다** — 고르기만 한다. 답의 내용은 고른 처리자에게 달려 있고, 라우터가 잘못 고르면 좋은 처리자가 있어도 엉뚱한 답이 나온다.\n- **라우팅과 오케스트레이션은 같은 말이다** — 라우터는 하나를 골라 넘기고 끝난다. 여러 처리자를 차례로 부르고 결과를 합치는 것은 오케스트레이터의 일이다.\n- **애매하면 가장 가까운 쪽으로 보내면 된다** — 억지로 보내면 엉뚱한 답이 확신에 찬 말투로 돌아온다. 기준 아래는 모름으로 따로 빼서 되묻는 편이 낫다."}],"figure":"```도해\n흐름: \"주소 변경하고 싶어\" 는 어디로 가나\n입력 :: 사용자가 문장 하나를 던진다\n분류기 :: 무엇에 대한 말인지 가른다. navigation\n신뢰도 :: 기준보다 낮으면 모름 쪽으로 돌린다\n규칙표 :: navigation 에 걸어둔 처리자를 꺼낸다\n처리자 :: 그 하나만 실행되어 답을 만든다\n= 라우터는 답을 만들지 않는다. 누가 만들지만 정한다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 요청을 가려 보내지 않으면 어떻게 되나\n라우터 없이 || 라우터로\n응답 :: 전부 답한다 || 하나만 답한다\n못 맞혔을 때 :: 못 찾는다고 답 || 맞는 쪽이 답\n처리자 추가 :: 코드를 고친다 || 규칙 한 줄\n= 답할 수 있는 곳이 여럿이면 고르는 자리가 따로 있어야 한다\n```\n\n\"급여명세서 보고 싶어\"라는 말이 메뉴 안내 담당에게 가면 못 찾는다는 답이 돌아온다. 반대로 모든 처리자가 각자 답하면 세 개의 답이 한꺼번에 나와서 어느 것을 봐야 할지 알 수 없다.\n\n라우터는 그 앞에 서서 하나만 고른다. 처리자를 새로 붙일 때도 규칙표에 한 줄을 더하면 되고, 부르는 쪽 코드는 건드리지 않는다."},"recap":"Routing은 요청을 읽고 누가 맡을지만 정하는 자리다. 답을 만들지 않으므로 잘 고르는 것과 못 고를 때 모름으로 빼는 것이 전부이고, 용건이 여러 개 섞인 요청은 여기서 끝나지 않는다.","check":[{"q":"처리자 셋이 한 질문에 저마다 답하면 사용자에게 무엇이 문제인가","at":"해결하는 문제"},{"q":"급여 요청인 걸 맞게 가렸는데도 답을 못 받는 경우가 있는 이유는","at":"작동 원리"},{"q":"\"주소도 바꾸고 육아휴직도 신청하고 싶어\"가 라우터만으로 안 되는 이유는","at":"비교"}],"myths":[{"wrong":"라우터가 답을 만든다","right":"고르기만 한다. 답의 내용은 고른 처리자에게 달려 있고, 라우터가 잘못 고르면 좋은 처리자가 있어도 엉뚱한 답이 나온다."},{"wrong":"라우팅과 오케스트레이션은 같은 말이다","right":"라우터는 하나를 골라 넘기고 끝난다. 여러 처리자를 차례로 부르고 결과를 합치는 것은 오케스트레이터의 일이다."},{"wrong":"애매하면 가장 가까운 쪽으로 보내면 된다","right":"억지로 보내면 엉뚱한 답이 확신에 찬 말투로 돌아온다. 기준 아래는 모름으로 따로 빼서 되묻는 편이 낫다."}],"cases":[{"label":"권한 확인","note":"급여 쪽으로 갈 요청이라도 조회 권한이 없으면 처리자에 닿기 전에 막고 안내로 돌린다."},{"label":"모름 처리","note":"분류 신뢰도가 기준 아래면 아무에게도 넘기지 않고 무엇을 원하는지 되묻는다."},{"label":"처리자 추가","note":"새 처리자를 붙일 때 규칙표에 한 줄만 더하고 기존 코드는 그대로 둔다."}],"dia":{"shape":"흐름","title":"\"주소 변경하고 싶어\" 는 어디로 가나","rows":[{"who":"입력","what":"사용자가 문장 하나를 던진다"},{"who":"분류기","what":"무엇에 대한 말인지 가른다. navigation"},{"who":"신뢰도","what":"기준보다 낮으면 모름 쪽으로 돌린다"},{"who":"규칙표","what":"navigation 에 걸어둔 처리자를 꺼낸다"},{"who":"처리자","what":"그 하나만 실행되어 답을 만든다"}],"sum":"라우터는 답을 만들지 않는다. 누가 만들지만 정한다"}},"ai--semantic-search":{"definition":"\"급여일\"로 물어도 \"임금 지급일\"이라고 적힌 문서가 걸린다. 글자를 맞춰보는 게 아니라 뜻을 숫자로 바꿔 거리를 재기 때문이다.","analogy":"사서에게 묻는 것. \"아이 키우는 데 필요한 책\"이라고만 해도 제목에 그 말이 없는 책을 꺼내 온다.","example":"노래 제목이 기억 안 나 가사 한 줄만 쳐도 그 곡이 맨 위에 올라오는 그 검색이다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"```도해\n층: 유사도 점수는 어디에서 갈리나\n0.7 위 :: 관련 있다고 보고 그대로 쓴다\n0.5 에서 0.7 :: 애매하다. 참고로만 두거나 버린다\n0.5 아래 :: 관련 없다고 보고 버린다\n= 문턱을 낮추면 엉뚱한 문서가 답의 근거로 섞여 들어온다\n```\n\n거리가 가까운 순서는 언제나 매겨진다. 전혀 관련 없는 문서라도 1등은 나온다는 뜻이다. 그래서 점수 문턱을 정해두고 그 아래는 아예 버린다.\n\n의미 검색만으로 안 되는 자리도 있다. \"제32조\"처럼 그 글자가 정확히 필요한 질문은 낱말 검색이 낫다. 그래서 의미 검색을 주로 두고 낱말이 정확히 들어맞은 문서에 점수를 얹는 방식을 함께 쓴다."},{"slot":"compare","label":"무엇과 비교되나","head":"📊 비교: 낱말 검색 vs 의미 검색","body":"| | 낱말 검색 | 의미 검색 |\n|---|---|---|\n| 맞춰보는 것 | 글자 | 뜻 |\n| 동의어 | 못 찾는다 | 찾는다 |\n| 오타 | 못 찾는다 | 어느 정도 견딘다 |\n| 속도 | 매우 빠르다 | 빠르다 |\n| 드는 것 | 거의 없다 | 벡터 DB 가 필요하다 |"},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **사내 규정 검색** — \"아이 키우기 위한 휴가\"라고 물어도 육아휴직 조항이 걸린다.\n- **말 바꿔 묻기** — \"돈 받는 날은?\"이라고 물어도 급여일 조항으로 이어진다.\n- **오타 섞인 질문** — \"육아휴지\"라고 쳐도 육아휴직 문서가 위에 올라온다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **의미 검색은 AI 가 질문을 이해하는 것이다** — 이해가 아니라 거리 계산이다. 질문과 문서를 숫자 배열로 바꿔 가까운 것을 고를 뿐이다.\n- **의미 검색이 낱말 검색보다 항상 낫다** — \"제32조\"처럼 그 글자가 정확히 필요한 질문에는 낱말 검색이 낫다. 그래서 둘을 같이 쓴다.\n- **유사도 1등이면 답이 거기 있다** — 가장 가까운 문서를 골랐다는 뜻일 뿐이다. 문턱을 두지 않으면 0.3짜리 문서도 1등이 된다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **문턱값을 정해두지 않으면 항상 무언가가 걸린다.** 순위는 언제나 매겨지므로 몇 점 아래는 버린다고 정해야 한다.\n- **아주 짧은 말은 잘 안 잡힌다.** 조사나 한 글자짜리 낱말에는 담긴 뜻이 적어서 거리 계산이 흔들린다."}],"figure":"```도해\n흐름: 급여일을 물으면 무슨 계산으로 문서를 고르나\n질문 :: 급여일이 언제냐는 문장이 들어온다\n임베딩 :: 그 문장을 숫자 배열로 바꾼다\n문서 벡터 :: 문서들도 미리 같은 방식으로 바꿔 두었다\n거리 재기 :: 질문과 각 문서 사이의 거리를 잰다\n< 결과 :: 가까운 순으로 위에서 몇 개만 돌려준다\n= 글자를 맞춰본 적이 없다. 거리만 쟀다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 질문에 없는 낱말로 적힌 문서는 어떻게 되나\n낱말 검색 || 의미 검색\n동의어 :: 임금은 못 찾음 || 같이 걸린다\n말 바꿔 묻기 :: 0건 || 뜻으로 찾는다\n오타 :: 0건 || 어느 정도 견딘다\n= 찾는 기준을 글자에서 뜻으로 옮긴 것이다\n```\n\n\"급여일이 언제죠?\"라고 물었는데 문서에는 \"임금 지급일은 25일입니다\"라고 적혀 있으면, 글자를 맞춰보는 검색은 이 문서를 놓친다. \"아이 키우려고 쉬고 싶은데요\"라고 물으면 \"육아휴직\"이라는 낱말이 질문에 없어서 역시 못 찾는다. \"육아휴지\"처럼 한 글자만 틀려도 결과가 0건이 된다.\n\n의미 검색은 글자 대신 뜻을 비교한다. 질문과 문서를 같은 방식으로 숫자 배열로 바꾸면 뜻이 가까운 것끼리 배열도 가까워진다. 그래서 \"급여\"와 \"임금\"과 \"월급\"이 한자리에 모인다."},"recap":"Semantic Search는 글자를 맞춰보는 대신 뜻을 숫자로 바꿔 거리를 재는 검색이다. 그래서 낱말이 다르거나 오타가 섞여도 찾아낸다. 다만 가까운 것을 고를 뿐이라 문턱을 두지 않으면 관련 없는 문서도 1등이 된다.","check":[{"q":"\"임금 지급일\"이라고만 적힌 문서를 \"급여일\"로 검색해 찾을 수 있는 이유는","at":"해결하는 문제"},{"q":"\"제32조\"를 찾을 때 낱말 검색을 같이 돌리는 이유는","at":"작동 원리"},{"q":"유사도 0.3짜리 문서가 결과 1등으로 올라오는 일이 왜 생기나","at":"흔한 오해"}],"myths":[{"wrong":"의미 검색은 AI 가 질문을 이해하는 것이다","right":"이해가 아니라 거리 계산이다. 질문과 문서를 숫자 배열로 바꿔 가까운 것을 고를 뿐이다."},{"wrong":"의미 검색이 낱말 검색보다 항상 낫다","right":"\"제32조\"처럼 그 글자가 정확히 필요한 질문에는 낱말 검색이 낫다. 그래서 둘을 같이 쓴다."},{"wrong":"유사도 1등이면 답이 거기 있다","right":"가장 가까운 문서를 골랐다는 뜻일 뿐이다. 문턱을 두지 않으면 0.3짜리 문서도 1등이 된다."}],"cases":[{"label":"사내 규정 검색","note":"\"아이 키우기 위한 휴가\"라고 물어도 육아휴직 조항이 걸린다."},{"label":"말 바꿔 묻기","note":"\"돈 받는 날은?\"이라고 물어도 급여일 조항으로 이어진다."},{"label":"오타 섞인 질문","note":"\"육아휴지\"라고 쳐도 육아휴직 문서가 위에 올라온다."}],"dia":{"shape":"흐름","title":"급여일을 물으면 무슨 계산으로 문서를 고르나","rows":[{"who":"질문","what":"급여일이 언제냐는 문장이 들어온다"},{"who":"임베딩","what":"그 문장을 숫자 배열로 바꾼다"},{"who":"문서 벡터","what":"문서들도 미리 같은 방식으로 바꿔 두었다"},{"who":"거리 재기","what":"질문과 각 문서 사이의 거리를 잰다"},{"who":"결과","what":"가까운 순으로 위에서 몇 개만 돌려준다","back":true}],"sum":"글자를 맞춰본 적이 없다. 거리만 쟀다"}},"ai--text-to-sql":{"definition":"DB에 있는 것을 보려면 SQL을 써야 하는데, 그걸 쓸 줄 아는 사람은 조직에서 소수다. 질문을 그대로 받아 쿼리로 옮겨주면 그 사이에 있던 사람이 빠진다.","analogy":"말이 안 통하는 손님 대신 주문을 옮겨주는 통역. 말은 통하지만 주방에 무엇이 있는지는 통역이 알고 있어야 한다.","example":"엑셀에서 원하는 합계를 내려고 함수 이름부터 검색해 본 적이 있다. 아는 사람에게는 한 줄이고 모르는 사람에게는 벽이다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"모델은 DB를 들여다보지 못한다. 질문과 함께 넘겨준 것만 보고 문장을 만든다. 정확한 SQL 이 나오려면 이만큼을 같이 넘겨야 한다.\n\n- **스키마** — 표 이름과 칸 이름, 자료형\n- **관계** — 어느 칸이 어느 표와 이어지는지\n- **용어** — \"매출\"이 어느 칸을 뜻하는지 적어둔 것\n- **예시 질문** — 이런 질문에는 이런 쿼리라는 견본\n\n모델은 모르는 것을 지어내므로 미리 알려준 만큼만 맞는다. 표 이름이나 칸 이름을 안 알려주면 그럴듯한 이름을 지어내고, 그 쿼리는 실행 단계에서 깨진다.\n\n만들어진 쿼리를 바로 실행하지 않는 것도 중요하다. 읽기 전용 계정으로 돌리고, `DELETE`나 `DROP`, `UPDATE` 같은 것이 섞여 있으면 실행 전에 막는다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **사내 데이터 조회** — 자주 나오는 질문을 담당자에게 부탁하지 않고 직접 물어본다.\n- **읽기 전용 통로** — 조회 권한만 있는 계정으로 실행해서 어떤 쿼리가 나와도 데이터가 바뀌지 않게 한다.\n- **쿼리 같이 보여주기** — 결과만 주지 않고 만들어진 SQL을 함께 띄워 무엇을 센 숫자인지 확인하게 한다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **말로 물으면 알아서 찾아준다** — 모델이 아는 것은 넘겨준 스키마뿐이다. 표와 칸 이름, \"매출\"이 어느 칸인지를 안 알려주면 있을 법한 이름을 지어내 틀린 쿼리를 만든다.\n- **결과가 나왔으면 맞는 것이다** — 문법이 맞는 SQL과 의도에 맞는 SQL은 다르다. 조건이 하나 빠져도 쿼리는 잘 돌고 숫자만 틀리게 나온다.\n- **읽기만 하는 기능이라 위험하지 않다** — 만들어지는 문장이 항상 읽기라는 보장이 없다. 읽기 전용 계정으로 돌리고 실행 전에 걸러야 그 말이 성립한다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **스키마를 통째로 넘기지 않는다.** 표가 많으면 넘길 것을 골라야 하고, 민감한 칸은 애초에 안 보이게 한다.\n- **결과를 그대로 보고서에 옮기지 않는다.** 어떤 쿼리로 나온 숫자인지 확인하지 않으면 틀린 수를 근거로 결정하게 된다."}],"figure":"```도해\n흐름: \"지난달 매출 얼마야\" 가 어떻게 답이 되나\n질문 :: 사람이 평소 쓰는 말로 묻는다\n스키마 :: 어떤 표에 어떤 칸이 있는지 같이 넘긴다\nLLM :: 그 정보를 보고 SQL 문장을 만든다\n검사 :: 읽기만 하는 쿼리인지 확인하고 통과시킨다\nDB :: 실행해서 행을 돌려준다\n< 답 :: 표나 문장으로 바꿔 보여준다\n= 사람은 SQL 을 안 쓰지만 DB 가 받는 것은 여전히 SQL 이다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: SQL 을 모르는 사람이 숫자를 보려면 어떻게 되나\n사람에게 부탁 || 말로 물어서\n걸리는 시간 :: 며칠씩 기다림 || 바로 나온다\n질문 바꾸기 :: 다시 부탁한다 || 다시 물으면 끝\n개발자 :: 조회 요청에 묶임 || 다른 일을 한다\n= 숫자를 궁금해하는 사람과 SQL 을 쓰는 사람을 떼어놓는 것이다\n```\n\n\"지난달 신규 가입자 몇 명이야\" 같은 질문은 매주 나온다. 물어볼 곳이 사람뿐이면 요청이 쌓여 며칠이 걸리고, 답을 받고 나서 조건 하나를 바꾸고 싶으면 처음부터 다시 부탁해야 한다.\n\nText-to-SQL은 그 왕복을 없앤다. 궁금한 사람이 직접 묻고 바로 다시 물을 수 있으므로, 조건을 바꿔가며 확인하는 일이 사람 손을 거치지 않는다."},"recap":"Text-to-SQL은 질문과 스키마를 받아 SQL을 만들어주는 기술이다. 모델은 알려준 만큼만 알기 때문에 스키마와 용어를 얼마나 잘 넘겨주느냐가 정확도를 정하고, 만들어진 쿼리는 실행 전에 한 번 걸러야 한다.","check":[{"q":"표 이름과 칸 이름을 안 넘겨주면 어떤 쿼리가 만들어지나","at":"작동 원리"},{"q":"쿼리가 오류 없이 돌았는데도 숫자가 틀릴 수 있는 이유는","at":"흔한 오해"},{"q":"조회만 하는 기능인데도 읽기 전용 계정으로 돌리는 이유는","at":"실제 사례"}],"myths":[{"wrong":"말로 물으면 알아서 찾아준다","right":"모델이 아는 것은 넘겨준 스키마뿐이다. 표와 칸 이름, \"매출\"이 어느 칸인지를 안 알려주면 있을 법한 이름을 지어내 틀린 쿼리를 만든다."},{"wrong":"결과가 나왔으면 맞는 것이다","right":"문법이 맞는 SQL과 의도에 맞는 SQL은 다르다. 조건이 하나 빠져도 쿼리는 잘 돌고 숫자만 틀리게 나온다."},{"wrong":"읽기만 하는 기능이라 위험하지 않다","right":"만들어지는 문장이 항상 읽기라는 보장이 없다. 읽기 전용 계정으로 돌리고 실행 전에 걸러야 그 말이 성립한다."}],"cases":[{"label":"사내 데이터 조회","note":"자주 나오는 질문을 담당자에게 부탁하지 않고 직접 물어본다."},{"label":"읽기 전용 통로","note":"조회 권한만 있는 계정으로 실행해서 어떤 쿼리가 나와도 데이터가 바뀌지 않게 한다."},{"label":"쿼리 같이 보여주기","note":"결과만 주지 않고 만들어진 SQL을 함께 띄워 무엇을 센 숫자인지 확인하게 한다."}],"dia":{"shape":"흐름","title":"\"지난달 매출 얼마야\" 가 어떻게 답이 되나","rows":[{"who":"질문","what":"사람이 평소 쓰는 말로 묻는다"},{"who":"스키마","what":"어떤 표에 어떤 칸이 있는지 같이 넘긴다"},{"who":"LLM","what":"그 정보를 보고 SQL 문장을 만든다"},{"who":"검사","what":"읽기만 하는 쿼리인지 확인하고 통과시킨다"},{"who":"DB","what":"실행해서 행을 돌려준다"},{"who":"답","what":"표나 문장으로 바꿔 보여준다","back":true}],"sum":"사람은 SQL 을 안 쓰지만 DB 가 받는 것은 여전히 SQL 이다"}},"ai--token":{"definition":"글자 단위도 아니고 단어 단위도 아니다. 자주 쓰이는 덩어리를 하나로 묶은 중간 크기라서, 영어는 대략 단어 하나가 토큰 하나에 가깝고 한글은 글자 하나가 여러 토큰이 되기도 한다.","analogy":"택배 요금의 부피 단위. 물건 개수도 무게도 아닌 별도 기준으로 값이 매겨진다. 같은 물건이라도 어떻게 포장했느냐에 따라 단위 수가 달라진다.","example":"문자를 몇 글자 더 썼다고 장문으로 넘어가 요금이 달라지던 일을 겪어 봤다면, 세는 단위가 따로 있다는 말을 이미 안다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"한국어는 영어보다 토큰을 훨씬 많이 쓴다. 학습 데이터에 영어가 압도적으로 많아서 영어 덩어리가 더 잘 묶여 있기 때문이다.\n\n```도해\n층: 같은 뜻을 쓰는 데 토큰이 얼마나 드나\n영어 문장 :: 단어 하나가 대체로 토큰 하나\n한글 문장 :: 글자 하나가 토큰 하나에서 셋\n코드 :: 들여쓰기와 기호가 각각 토큰\n= 같은 내용도 한국어로 쓰면 비용이 몇 배가 된다\n```\n\n문맥 창도 토큰으로 센다. 창이 8,000토큰이면 대화 기록과 질문과 답을 다 합쳐 8,000을 넘을 수 없다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **요금 계산** — API 값은 입력 토큰과 출력 토큰을 따로 센다. 출력이 대체로 더 비싸다.\n- **문맥 창 관리** — 대화가 길어지면 앞부분을 요약해 넣어 토큰을 줄인다.\n- **프롬프트 다듬기** — 같은 지시를 짧게 쓰면 매 요청마다 그만큼 아낀다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **토큰이 단어와 같다** — 다르다. `unbelievable`은 세 토큰으로 쪼개지고, 한글 `안녕하세요`도 여러 토큰이다.\n- **글자 수로 비용을 계산할 수 있다** — 언어마다 비율이 달라서 한국어를 영어 기준으로 계산하면 크게 어긋난다.\n- **입력만 돈이 든다** — 모델이 만들어낸 출력도 토큰으로 센다. 긴 답변을 요구하면 그만큼 비싸진다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **긴 대화 기록을 통째로 넣지 않는다.** 매 요청마다 전체가 다시 계산되어 비용이 대화 길이의 제곱처럼 늘어난다.\n- **한국어 비용을 따로 잰다.** 영어 기준 견적으로 계획하면 실제 청구가 몇 배로 나온다."}],"figure":"```도해\n흐름: 입력한 글이 어떻게 요금이 되나\n사용자 :: \"안녕하세요\" 를 입력한다\n토크나이저 :: 자주 쓰이는 덩어리로 쪼갠다\n토크나이저 :: 조각마다 번호를 붙인다\n모델 :: 번호 목록을 받아 다음 번호를 예측한다\n요금 :: 넣은 토큰 수 + 나온 토큰 수로 계산된다\n= 글자 수가 아니라 토큰 수가 비용이자 한계다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 쪼개는 단위를 무엇으로 하나\n글자 단위 || 토큰 단위\n목록 크기 :: 작다 || 적당하다\n문맥 길이 :: 금방 찬다 || 여유가 있다\n처음 보는 말 :: 처리된다 || 조각으로 처리된다\n= 글자는 너무 잘고 단어는 너무 많아서 그 사이를 고른 것이다\n```\n\n단어 단위로 쪼개면 사전에 없는 말을 만났을 때 처리할 수 없다. 신조어, 오타, 고유명사가 전부 미지의 단어가 된다.\n\n글자 단위로 쪼개면 그 문제는 없지만 목록이 너무 길어진다. 문장 하나가 수십 조각이 되어 문맥 창을 금방 채운다.\n\n토큰은 그 사이다. 자주 나오는 덩어리는 하나로 묶고, 드문 말은 조각으로 나눠서 둘 다 처리한다."},"recap":"Token은 모델이 글을 다루는 최소 조각이자 비용과 한계의 단위다. 글자도 단어도 아닌 중간 크기이고, 한국어는 같은 내용에 영어보다 훨씬 많은 토큰을 쓴다.","check":[{"q":"같은 내용을 한국어로 쓸 때 비용이 더 나오는 이유는","at":"작동 원리"},{"q":"대화가 길어질수록 요청 하나의 비용이 늘어나는 이유는","at":"주의사항"},{"q":"짧게 물었는데 답이 길게 오면 요금이 왜 더 나오나","at":"흔한 오해"}],"myths":[{"wrong":"토큰이 단어와 같다","right":"다르다. `unbelievable`은 세 토큰으로 쪼개지고, 한글 `안녕하세요`도 여러 토큰이다."},{"wrong":"글자 수로 비용을 계산할 수 있다","right":"언어마다 비율이 달라서 한국어를 영어 기준으로 계산하면 크게 어긋난다."},{"wrong":"입력만 돈이 든다","right":"모델이 만들어낸 출력도 토큰으로 센다. 긴 답변을 요구하면 그만큼 비싸진다."}],"cases":[{"label":"요금 계산","note":"API 값은 입력 토큰과 출력 토큰을 따로 센다. 출력이 대체로 더 비싸다."},{"label":"문맥 창 관리","note":"대화가 길어지면 앞부분을 요약해 넣어 토큰을 줄인다."},{"label":"프롬프트 다듬기","note":"같은 지시를 짧게 쓰면 매 요청마다 그만큼 아낀다."}],"dia":{"shape":"흐름","title":"입력한 글이 어떻게 요금이 되나","rows":[{"who":"사용자","what":"\"안녕하세요\" 를 입력한다"},{"who":"토크나이저","what":"자주 쓰이는 덩어리로 쪼갠다"},{"who":"토크나이저","what":"조각마다 번호를 붙인다"},{"who":"모델","what":"번호 목록을 받아 다음 번호를 예측한다"},{"who":"요금","what":"넣은 토큰 수 + 나온 토큰 수로 계산된다"}],"sum":"글자 수가 아니라 토큰 수가 비용이자 한계다"}},"ai--transformer":{"definition":"앞에서부터 한 낱말씩 읽던 RNN 을 대신했다. GPT 와 BERT 를 비롯한 요즘 언어 모델이 전부 이 구조 위에 서 있다.","analogy":"책 한 쪽을 통째로 펼쳐 놓고 보는 것. 3번째 줄과 20번째 줄이 이어진다는 걸 한눈에 알아챈다.","example":"번역기에 한 문장을 넣으면 어순이 통째로 뒤집힌 문장이 나온다. 앞에서부터 한 낱말씩 바꿔서는 나올 수 없는 결과다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"한 겹은 네 부품으로 되어 있다.\n\n| 부품 | 하는 일 |\n|---|---|\n| **위치 인코딩** | 몇 번째 조각인지를 값에 실어 준다 |\n| **셀프 어텐션** | 조각끼리 서로 얼마나 볼지 정한다 |\n| **멀티 헤드** | 같은 일을 여러 갈래로 나눠 따로 본다 |\n| **피드포워드** | 섞인 값을 한 번 더 변환한다 |\n\n이 한 겹을 여러 번 쌓아 올린 것이 모델의 깊이다.\n\n어텐션은 조각마다 다른 조각을 얼마나 볼지 점수로 매기고, 그 점수를 가중치 삼아 값을 섞는다. \"나는 학교에 갔다\"에서 \"갔다\"는 \"학교에\"를 많이 보고 \"나는\"은 조금만 보는 식이다.\n\n멀티 헤드는 그 보기를 여러 갈래로 나눈다. 한 갈래는 문법 쪽 관계를, 다른 갈래는 의미 쪽 관계를 보게 갈라 두면 한 갈래만 쓸 때보다 잡히는 게 많다.\n\n순서를 안 보고 관계만 재면 \"나는 학교에 갔다\"와 \"학교에 나는 갔다\"가 같아진다. 그래서 몇 번째 조각인지를 값에 실어 주는데, 이것을 위치 인코딩이라고 한다."},{"slot":"compare","label":"무엇과 비교되나","head":"📊 비교: GPT vs BERT vs T5","body":"| | GPT | BERT | T5 |\n|---|---|---|---|\n| 쓰는 부분 | 디코더만 | 인코더만 | 둘 다 |\n| 하는 일 | 다음 낱말 예측 | 가려진 낱말 맞히기 | 입력을 다른 글로 |\n| 맞는 자리 | 글 생성 | 분류, 질의응답 | 번역, 요약 |"},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **글 생성** — \"안녕하세요, 저는\" 다음에 올 조각을 하나씩 이어 붙여 문장을 만든다.\n- **빈칸 맞히기** — \"나는 [MASK]에 갔다\"에서 가려진 자리를 앞뒤를 다 보고 채운다.\n- **번역과 요약** — 입력을 통째로 읽고 다른 글로 바꿔 내놓는다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **Transformer 는 문장을 순서대로 읽는다** — 전부 펼쳐 놓고 동시에 본다. 순서는 위치 인코딩으로 따로 실어 주는 것이라 그걸 빼면 낱말 순서를 아예 구별하지 못한다.\n- **Attention 이 곧 이해다** — 어느 조각을 얼마나 볼지 정한 가중치일 뿐이다. 값을 섞는 비율이지 뜻을 읽어낸 결과가 아니다.\n- **입력이 길어져도 계산은 비슷하다** — 모든 조각 쌍을 재므로 조각 수가 두 배면 계산은 네 배가 된다. 긴 입력이 부담스러운 이유가 여기 있다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **입력이 길수록 메모리가 제곱으로 는다.** 긴 문서를 그대로 넣기 전에 자르거나 다른 어텐션 방식을 찾아본다.\n- **작은 데이터로는 잘 되지 않는다.** 학습에 아주 많은 양이 필요해서 대개 이미 학습된 모델을 가져다 쓴다."}],"figure":"```도해\n흐름: 문장 하나가 Transformer 를 지나며 무엇을 겪나\n토큰 :: 문장을 조각내 각각 숫자 배열로 바꾼다\n위치 표시 :: 몇 번째 조각인지를 그 배열에 더한다\n어텐션 :: 모든 조각이 서로를 얼마나 볼지 잰다\n섞기 :: 많이 본 쪽 값을 더 얹어 새 배열을 만든다\n@ 다시 어텐션으로 :: 같은 일을 여러 겹 쌓아 결과를 낸다\n= 순서대로 읽지 않고 전부 펼쳐 놓은 채 관계만 잰다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 문장을 앞에서부터 한 낱말씩 읽으면 어떻게 되나\n한 낱말씩 || 한꺼번에\n처리 순서 :: 앞이 끝나야 뒤 || 동시에 본다\nGPU :: 나눠 쓸 수 없다 || 병렬로 돌린다\n먼 관계 :: 갈수록 흐려진다 || 거리와 무관\n= 순서를 버리고 관계를 직접 재는 쪽으로 바꾼 것이다\n```\n\nRNN 은 첫 낱말을 처리해야 두 번째를 처리할 수 있다. 순서를 지켜야 하니 GPU 를 여러 장 붙여도 나눠 돌릴 수 없어서, 백만 문장을 학습하는 데 며칠에서 몇 주가 걸렸다. 멀리 떨어진 관계도 약했다. \"어제 시장에서 산 사과를 오늘 먹었다\"에서 \"사과\"와 \"먹었다\"는 여러 낱말 건너에 있어 앞의 정보가 뒤로 오는 동안 흐려진다.\n\nTransformer 는 문장 전체를 펼쳐 놓고 모든 조각 쌍의 관계를 한 번에 잰다. 순서에 묶이지 않으니 나눠 돌릴 수 있어 같은 학습이 몇 시간에서 하루 규모로 줄었다. 거리와 상관없이 \"사과\"와 \"먹었다\"가 곧바로 이어진다."},"recap":"Transformer는 문장의 조각들을 한꺼번에 펼쳐 놓고 서로를 얼마나 볼지 재는 구조다. 순서에 묶이지 않아 나눠 돌릴 수 있고 멀리 떨어진 낱말 사이의 관계도 흐려지지 않는다. 대신 모든 쌍을 재느라 입력이 길어질수록 계산이 제곱으로 늘어난다.","check":[{"q":"\"나는 학교에 갔다\"와 \"학교에 나는 갔다\"를 구별하려면 무엇이 필요한가","at":"작동 원리"},{"q":"RNN 은 GPU 를 여러 장 붙여도 학습이 빨라지지 않는데 그 이유는","at":"해결하는 문제"},{"q":"입력 조각 수를 두 배로 늘리면 계산량은 몇 배가 되나","at":"흔한 오해"}],"myths":[{"wrong":"Transformer 는 문장을 순서대로 읽는다","right":"전부 펼쳐 놓고 동시에 본다. 순서는 위치 인코딩으로 따로 실어 주는 것이라 그걸 빼면 낱말 순서를 아예 구별하지 못한다."},{"wrong":"Attention 이 곧 이해다","right":"어느 조각을 얼마나 볼지 정한 가중치일 뿐이다. 값을 섞는 비율이지 뜻을 읽어낸 결과가 아니다."},{"wrong":"입력이 길어져도 계산은 비슷하다","right":"모든 조각 쌍을 재므로 조각 수가 두 배면 계산은 네 배가 된다. 긴 입력이 부담스러운 이유가 여기 있다."}],"cases":[{"label":"글 생성","note":"\"안녕하세요, 저는\" 다음에 올 조각을 하나씩 이어 붙여 문장을 만든다."},{"label":"빈칸 맞히기","note":"\"나는 [MASK]에 갔다\"에서 가려진 자리를 앞뒤를 다 보고 채운다."},{"label":"번역과 요약","note":"입력을 통째로 읽고 다른 글로 바꿔 내놓는다."}],"dia":{"shape":"흐름","title":"문장 하나가 Transformer 를 지나며 무엇을 겪나","rows":[{"who":"토큰","what":"문장을 조각내 각각 숫자 배열로 바꾼다"},{"who":"위치 표시","what":"몇 번째 조각인지를 그 배열에 더한다"},{"who":"어텐션","what":"모든 조각이 서로를 얼마나 볼지 잰다"},{"who":"섞기","what":"많이 본 쪽 값을 더 얹어 새 배열을 만든다"}],"sum":"순서대로 읽지 않고 전부 펼쳐 놓은 채 관계만 잰다","loop":{"who":"다시 어텐션으로","what":"같은 일을 여러 겹 쌓아 결과를 낸다"}}},"ai--vector-db":{"definition":"임베딩으로 만든 숫자 목록을 수백만 개 넣어두고, 질문 벡터가 들어오면 그와 가장 가까운 것들을 골라준다. 일반 데이터베이스가 값이 같은 것을 찾는다면 이쪽은 값이 비슷한 것을 찾는다.","analogy":"도서관의 주제별 배가. 제목이 정확히 기억나지 않아도 관련 서가로 가면 비슷한 책들이 모여 있다. 청구기호가 정확히 일치해야 찾을 수 있는 방식과 다르다.","example":"쇼핑 앱에서 물건 사진을 찍어 올리면 비슷하게 생긴 상품들이 줄줄이 뜨는 그 검색이다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"```도해\n흐름: 넣어둔 문서가 골라져 나오기까지 무엇을 거치나\n임베딩 :: 문서를 벡터로 만든다\n색인 :: 이웃 관계를 미리 계산해 지도를 만든다\n검색 :: 질문이 오면 지도를 타고 후보를 좁힌다\n필터 :: 부서나 권한 같은 조건으로 거른다\n= 색인을 만드는 시간이 들지만 그 뒤로는 검색이 싸진다\n```\n\n메타데이터 필터가 실무에서 중요하다. 벡터로 가까운 것을 찾되 \"이 사용자가 볼 수 있는 문서\"로 한정하지 않으면 권한 없는 내용이 검색된다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **RAG 저장소** — 사내 문서를 조각내 넣어두고 질문과 가까운 조각을 꺼낸다.\n- **이미지 검색** — 사진을 벡터로 넣어두면 비슷한 사진을 찾을 수 있다.\n- **중복 문의 묶기** — 표현이 다른 같은 문의를 벡터 거리로 묶어 한 번에 처리한다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **벡터 DB가 항상 정확한 답을 준다** — 근사 검색이라 가장 가까운 것을 놓칠 수 있다. 정확도와 속도를 설정으로 조절한다.\n- **일반 데이터베이스를 대체한다** — 대체하지 않는다. 주문 내역처럼 정확히 일치하는 조회는 여전히 관계형이 맞다.\n- **넣기만 하면 검색이 좋아진다** — 검색 품질은 임베딩 모델과 문서를 어떻게 잘랐는지가 정한다. 저장소는 빠르게 찾아줄 뿐이다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **권한 필터를 벡터 검색에 같이 건다.** 나중에 거르면 이미 본 문서가 나간 뒤다.\n- **모델을 바꾸면 전부 다시 넣어야 한다.** 좌표계가 달라져서 옛 벡터와 새 벡터를 비교할 수 없다."}],"figure":"```도해\n흐름: 백만 개 중에서 가까운 셋을 어떻게 찾나\n질문 :: 벡터 하나가 들어온다\n색인 :: 미리 만들어둔 이웃 지도를 탄다\n색인 :: 가까운 후보 구역으로 건너뛴다\n색인 :: 그 안에서만 실제 거리를 잰다\n< 결과 :: 가장 가까운 셋을 돌려준다\n= 백만 개를 다 재지 않는 대신 정확도를 조금 내주는 거래다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 백만 개 벡터에서 가까운 것을 어떻게 찾나\n일반 DB |=| 벡터 DB\n검색 방식 :: 전부 하나씩 계산 || 색인으로 건너뛴다\n소요 시간 :: 수 초 || 수십 밀리초\n정확도 :: 완벽 || 거의 정확\n= 전부 재는 대신 대부분 맞는 답을 훨씬 빨리 주는 쪽을 고른 것이다\n```\n\n벡터 검색은 원래 무거운 작업이다. 백만 개가 있으면 백만 번 거리를 계산해야 한다. 관계형 데이터베이스에 벡터를 넣고 매번 전부 계산하면 검색 하나에 수 초가 걸린다.\n\n벡터 DB는 이웃 관계를 미리 지도로 만들어둔다. 검색할 때 그 지도를 따라 후보 구역까지 건너뛰고 그 안에서만 실제로 계산한다. 완벽한 답을 포기하는 대신 속도를 얻는 방식이라 근사 최근접 이웃 검색이라고 부른다."},"compose":{"label":"무엇으로 되어 있나","head":"🧱 구성","body":"```도해\n층: 벡터 DB 안에는 무엇이 쌓여 있나\n색인 :: 이웃 지도. 어디부터 뒤질지 정한다\n벡터 :: 뜻을 숫자로 바꿔 놓은 목록\n원본 조각 :: 검색에 걸렸을 때 실제로 꺼내 주는 글\n= 색인은 벡터 위에 얹혀 있고, 벡터는 원본 조각을 가리키는 표일 뿐이다\n```"},"recap":"Vector DB는 벡터를 저장하고 가까운 것을 빠르게 찾아주는 저장소다. 완벽한 답 대신 속도를 택한 구조이고, 검색 품질 자체는 임베딩과 문서 자르기가 정한다.","check":[{"q":"백만 개를 다 계산하지 않는데 어떻게 가까운 것을 찾나","at":"해결하는 문제"},{"q":"검색 결과가 나쁠 때 저장소를 바꾸는 게 답이 아닌 이유는","at":"흔한 오해"},{"q":"권한 필터를 검색 뒤에 적용하면 무엇이 문제인가","at":"주의사항"}],"myths":[{"wrong":"벡터 DB가 항상 정확한 답을 준다","right":"근사 검색이라 가장 가까운 것을 놓칠 수 있다. 정확도와 속도를 설정으로 조절한다."},{"wrong":"일반 데이터베이스를 대체한다","right":"대체하지 않는다. 주문 내역처럼 정확히 일치하는 조회는 여전히 관계형이 맞다."},{"wrong":"넣기만 하면 검색이 좋아진다","right":"검색 품질은 임베딩 모델과 문서를 어떻게 잘랐는지가 정한다. 저장소는 빠르게 찾아줄 뿐이다."}],"cases":[{"label":"RAG 저장소","note":"사내 문서를 조각내 넣어두고 질문과 가까운 조각을 꺼낸다."},{"label":"이미지 검색","note":"사진을 벡터로 넣어두면 비슷한 사진을 찾을 수 있다."},{"label":"중복 문의 묶기","note":"표현이 다른 같은 문의를 벡터 거리로 묶어 한 번에 처리한다."}],"dia":{"shape":"흐름","title":"백만 개 중에서 가까운 셋을 어떻게 찾나","rows":[{"who":"질문","what":"벡터 하나가 들어온다"},{"who":"색인","what":"미리 만들어둔 이웃 지도를 탄다"},{"who":"색인","what":"가까운 후보 구역으로 건너뛴다"},{"who":"색인","what":"그 안에서만 실제 거리를 잰다"},{"who":"결과","what":"가장 가까운 셋을 돌려준다","back":true}],"sum":"백만 개를 다 재지 않는 대신 정확도를 조금 내주는 거래다"}}};
